// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ID17Launch} from "./interfaces/ID17.sol";
import {ID17LaunchFactory} from "./interfaces/ID17LaunchFactory.sol";

interface IV2RouterView {
    function factory() external view returns (address);
}

interface ID17FeeConfigView {
    function currentFee() external view returns (address recipient, uint16 bps);
}

contract D17Factory {
    bytes32 public constant D17_FACTORY_ID = keccak256("D17_FACTORY_V15_HARDENED");
    uint16 public constant BPS = 10_000;
    // Creator treasury fee cap (V14: 20%). Every successful commitment keeps at least
    // BPS - MAX_TREASURY_BPS - D17FeeConfig.MAX_PROTOCOL_FEE_BPS = 88% for the locked pool.
    uint16 public constant MAX_TREASURY_BPS = 1_000;
    uint16 public constant MAX_MANUAL_DISTRIBUTION_BPS = 1_000;
    // Refund penalties go to the official pool, never to the creator; rounds 3-4 penalty
    // sits between the fixed early penalty (1%) and 25% (V14: 0-50%).
    uint16 public constant MIN_REFUND_PENALTY_BPS = 100;
    uint16 public constant MAX_REFUND_PENALTY_BPS = 2_500;
    uint8 public constant ROUND_COUNT = 5;
    uint256 public constant MAX_DESCRIPTION_BYTES = 512;
    uint256 public constant MAX_LINKS = 8;
    uint256 public constant MAX_LINK_TYPE_BYTES = 32;
    uint256 public constant MAX_LINK_URL_BYTES = 128;
    uint256 public constant MAX_LOGO_SVG_URI_BYTES = 8_192;
    string public constant LOGO_SVG_BASE64_PREFIX = "data:image/svg+xml;base64,";
    uint256 public constant MIN_COMMIT_WETH = 1e15;
    uint256 public constant MIN_LP_TOKENS = 1e18;
    uint256 public constant MIN_ROUND_ALLOCATION_TOKENS = 1e18;
    uint256 public constant MIN_ANCHOR_PRICE_WAD = 1e6;
    uint32 public constant MIN_ROUND_SECONDS = 60;
    uint32 public constant MAX_ROUND_SECONDS = 90 days;
    uint32 public constant MAX_REFUND_SECONDS = 30 days;
    uint32 public constant MAX_SETTLEMENT_SECONDS = 30 days;
    uint64 public constant MAX_START_DELAY = 365 days;
    // Ethereum mainnet floors: a launch must be announced on-chain at least a day before it
    // starts and every window must stay open long enough for ordinary wallets to act, so no
    // launch can be run as a stealth/bot-only event. Test networks keep short windows.
    uint32 public constant MAINNET_MIN_WINDOW_SECONDS = 1 hours;
    uint64 public constant MAINNET_MIN_START_DELAY = 1 days;

    address public owner;
    address public immutable weth;
    address public immutable router;
    address public immutable feeConfig;
    address public launchFactory;
    address public lockerFactory;
    bool public launchFactoryPinned;
    bool public lockerFactoryPinned;

    struct LaunchRecord {
        bool canonical;
        address creator;
        address token;
        address liquidityVault;
        bytes32 rulesHash;
    }

    mapping(address => LaunchRecord) public launches;
    mapping(address => bool) public isLocker;
    mapping(address => address[]) private lockersByOwner;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event LaunchCreated(
        address indexed creator,
        address indexed launch,
        address indexed token,
        address liquidityVault,
        bytes32 rulesHash
    );
    event LaunchMetadataPublished(
        address indexed launch,
        bytes32 indexed metadataHash,
        string description,
        string logoSvgUri,
        string[] linkTypes,
        string[] linkUrls
    );
    event ManualDistributionConfigured(address indexed launch, address indexed recipient, uint256 amount);
    event LockerRegistered(address indexed owner, address indexed locker, address indexed manager);
    event LaunchFactoryPinned(address indexed launchFactory);
    event LockerFactoryPinned(address indexed lockerFactory);

    modifier onlyOwner() {
        require(msg.sender == owner, "NOT_OWNER");
        _;
    }

    constructor(address owner_, address weth_, address router_, address feeConfig_) {
        require(owner_ != address(0), "OWNER_ZERO");
        require(weth_ != address(0), "WETH_ZERO");
        require(router_ != address(0), "ROUTER_ZERO");
        require(weth_.code.length > 0, "WETH_NO_CODE");
        require(router_.code.length > 0, "ROUTER_NO_CODE");
        require(IV2RouterView(router_).factory() != address(0), "ROUTER_FACTORY_ZERO");
        require(feeConfig_.code.length > 0, "FEE_CONFIG_NO_CODE");
        owner = owner_;
        weth = weth_;
        router = router_;
        feeConfig = feeConfig_;
        emit OwnershipTransferred(address(0), owner_);
    }

    function registerLockerFor(address lockerOwner, address locker) external {
        require(lockerFactoryPinned && msg.sender == lockerFactory, "NOT_LOCKER_FACTORY");
        require(lockerOwner != address(0), "LOCKER_OWNER_ZERO");
        require(locker != address(0), "LOCKER_ZERO");
        require(locker.code.length > 0, "LOCKER_NO_CODE");
        require(!isLocker[locker], "LOCKER_REGISTERED");
        isLocker[locker] = true;
        lockersByOwner[lockerOwner].push(locker);
        emit LockerRegistered(lockerOwner, locker, msg.sender);
    }

    function pinLockerFactory(address lockerFactory_) external onlyOwner {
        require(!lockerFactoryPinned, "LOCKER_FACTORY_PINNED");
        require(lockerFactory_ != address(0), "LOCKER_FACTORY_ZERO");
        require(lockerFactory_.code.length > 0, "LOCKER_FACTORY_NO_CODE");
        lockerFactory = lockerFactory_;
        lockerFactoryPinned = true;
        emit LockerFactoryPinned(lockerFactory_);
    }

    function pinLaunchFactory(address launchFactory_) external onlyOwner {
        require(!launchFactoryPinned, "LAUNCH_FACTORY_PINNED");
        require(launchFactory_ != address(0), "LAUNCH_FACTORY_ZERO");
        require(launchFactory_.code.length > 0, "LAUNCH_FACTORY_NO_CODE");
        launchFactory = launchFactory_;
        launchFactoryPinned = true;
        emit LaunchFactoryPinned(launchFactory_);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "OWNER_ZERO");
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }

    function renounceOwnership() external onlyOwner {
        require(launchFactoryPinned, "LAUNCH_FACTORY_UNLOCKED");
        require(lockerFactoryPinned, "LOCKER_FACTORY_UNLOCKED");
        emit OwnershipTransferred(owner, address(0));
        owner = address(0);
    }

    function lockersOfOwner(address lockerOwner) external view returns (address[] memory) {
        return lockersByOwner[lockerOwner];
    }

    function createLaunch(ID17LaunchFactory.LaunchConfig calldata config)
        external
        returns (address token, address launch, address liquidityVault)
    {
        require(launchFactoryPinned, "LAUNCH_FACTORY_UNLOCKED");
        require(lockerFactoryPinned, "LOCKER_FACTORY_UNLOCKED");
        // No launch can exist while a factory admin key does.
        require(owner == address(0), "FACTORY_NOT_RENOUNCED");
        _validateConfig(config);

        (address feeRecipient, uint16 feeBps) = ID17FeeConfigView(feeConfig).currentFee();
        require(feeBps <= config.maxProtocolFeeBps, "PROTOCOL_FEE_ABOVE_MAX");
        (token, launch, liquidityVault) =
            ID17LaunchFactory(launchFactory).deployLaunch(config, msg.sender, feeRecipient, feeBps);
        bytes32 rules = ID17Launch(launch).rulesHash();
        launches[launch] = LaunchRecord({
            canonical: true,
            creator: msg.sender,
            token: token,
            liquidityVault: liquidityVault,
            rulesHash: rules
        });

        (string[] memory linkTypes, string[] memory linkUrls) = _metadataLinkArrays(config.links);

        emit LaunchCreated(msg.sender, launch, token, liquidityVault, rules);
        emit ManualDistributionConfigured(launch, msg.sender, config.manualDistributionTokens);
        emit LaunchMetadataPublished(
            launch,
            ID17Launch(launch).metadataHash(),
            config.description,
            config.logoSvgUri,
            linkTypes,
            linkUrls
        );
    }

    function isCanonicalLaunch(address launch, bytes32 rulesHash) external view returns (bool) {
        LaunchRecord storage record = launches[launch];
        return record.canonical && record.rulesHash == rulesHash;
    }

    function _validateConfig(ID17LaunchFactory.LaunchConfig calldata config) internal view {
        require(bytes(config.tokenName).length > 0 && bytes(config.tokenName).length <= 64, "TOKEN_NAME");
        require(bytes(config.tokenSymbol).length > 0 && bytes(config.tokenSymbol).length <= 16, "TOKEN_SYMBOL");
        _validateJsonSafe(config.tokenName, "TOKEN_NAME_JSON");
        _validateJsonSafe(config.tokenSymbol, "TOKEN_SYMBOL_JSON");
        _validateMetadata(config);
        require(config.tokenSupply > 0, "SUPPLY_ZERO");
        require(config.saleTokens > 0, "SALE_ZERO");
        require(config.lpTokens >= MIN_LP_TOKENS, "LP_TOO_LOW");
        require(
            config.saleTokens + config.lpTokens + config.manualDistributionTokens + config.deadTokens
                == config.tokenSupply,
            "SUPPLY_SPLIT"
        );
        require(
            config.manualDistributionTokens * BPS <= config.tokenSupply * MAX_MANUAL_DISTRIBUTION_BPS,
            "MANUAL_ABOVE_CAP"
        );
        if (config.deadTokens > 0) {
            require(config.deadRecipient == 0x000000000000000000000000000000000000dEaD, "DEAD_RECIPIENT");
        }
        require(config.treasury != address(0), "TREASURY_ZERO");
        bool mainnet = block.chainid == 1;
        uint32 minWindow = mainnet ? MAINNET_MIN_WINDOW_SECONDS : 1;
        uint32 minRound = mainnet ? MAINNET_MIN_WINDOW_SECONDS : MIN_ROUND_SECONDS;
        require(config.startTime >= block.timestamp + (mainnet ? MAINNET_MIN_START_DELAY : 0), "START_TOO_SOON");
        require(config.startTime <= block.timestamp + MAX_START_DELAY, "START_TOO_FAR");
        require(config.refundSeconds >= minWindow && config.refundSeconds <= MAX_REFUND_SECONDS, "REFUND_SECONDS");
        require(
            config.settlementSeconds >= minWindow && config.settlementSeconds <= MAX_SETTLEMENT_SECONDS,
            "SETTLEMENT_SECONDS"
        );
        require(config.minCommitWeth >= MIN_COMMIT_WETH, "MIN_COMMIT_TOO_LOW");
        require(config.minPhase1Weth >= config.minCommitWeth, "MIN_PHASE1_WETH");
        require(config.minAnchorPriceWad >= MIN_ANCHOR_PRICE_WAD, "MIN_ANCHOR_PRICE_TOO_LOW");
        require(config.treasuryBps <= MAX_TREASURY_BPS, "TREASURY_BPS");
        require(
            config.refundPenaltyBps >= MIN_REFUND_PENALTY_BPS && config.refundPenaltyBps <= MAX_REFUND_PENALTY_BPS,
            "REFUND_PENALTY_BPS"
        );

        uint256 shareTotal;
        for (uint256 i; i < ROUND_COUNT; i++) {
            require(config.roundSeconds[i] >= minRound && config.roundSeconds[i] <= MAX_ROUND_SECONDS, "ROUND_SECONDS");
            require(config.roundSharesBps[i] > 0, "ROUND_SHARE_ZERO");
            require(
                config.saleTokens * config.roundSharesBps[i] / BPS >= MIN_ROUND_ALLOCATION_TOKENS,
                "ROUND_ALLOCATION_TOO_LOW"
            );
            shareTotal += config.roundSharesBps[i];
        }

        require(shareTotal == BPS, "ROUND_SHARE_TOTAL");
    }

    function _validateMetadata(ID17LaunchFactory.LaunchConfig calldata config) internal pure {
        require(bytes(config.description).length <= MAX_DESCRIPTION_BYTES, "DESCRIPTION_BYTES");
        _validateJsonSafe(config.description, "DESCRIPTION_JSON");
        require(config.links.length <= MAX_LINKS, "LINKS");

        for (uint256 i; i < config.links.length; i++) {
            _validateLinkType(config.links[i].linkType);
            _validateLinkUrl(config.links[i].url);
        }

        bytes calldata logo = bytes(config.logoSvgUri);
        require(logo.length <= MAX_LOGO_SVG_URI_BYTES, "LOGO_BYTES");
        if (logo.length > 0) {
            bytes memory prefix = bytes(LOGO_SVG_BASE64_PREFIX);
            require(_startsWith(config.logoSvgUri, prefix), "LOGO_PREFIX");
            require(logo.length > prefix.length, "LOGO_EMPTY");
            for (uint256 i = prefix.length; i < logo.length; i++) {
                require(_isBase64Byte(logo[i]), "LOGO_BASE64");
            }
        }
    }

    function _validateLinkType(string calldata value) internal pure {
        bytes calldata data = bytes(value);
        require(data.length > 0 && data.length <= MAX_LINK_TYPE_BYTES, "LINK_TYPE");
        for (uint256 i; i < data.length; i++) {
            bytes1 char = data[i];
            bool ok = (char >= 0x61 && char <= 0x7a) || (char >= 0x30 && char <= 0x39) || char == 0x2d;
            require(ok, "LINK_TYPE_CHARS");
        }
    }

    function _validateLinkUrl(string calldata value) internal pure {
        bytes calldata data = bytes(value);
        require(data.length > 0 && data.length <= MAX_LINK_URL_BYTES, "LINK_URL");
        require(_startsWith(value, bytes("https://")), "LINK_URL_SCHEME");
        _validateJsonSafe(value, "LINK_URL_JSON");
    }

    function _validateJsonSafe(string calldata value, string memory reason) internal pure {
        bytes calldata data = bytes(value);
        for (uint256 i; i < data.length; i++) {
            bytes1 char = data[i];
            if (char == 0x22 || char == 0x5c || char < 0x20) revert(reason);
        }
    }

    function _startsWith(string calldata value, bytes memory prefix) internal pure returns (bool) {
        bytes calldata data = bytes(value);
        if (data.length < prefix.length) return false;
        for (uint256 i; i < prefix.length; i++) {
            if (data[i] != prefix[i]) return false;
        }
        return true;
    }

    function _isBase64Byte(bytes1 char) internal pure returns (bool) {
        return (char >= 0x41 && char <= 0x5a)
            || (char >= 0x61 && char <= 0x7a)
            || (char >= 0x30 && char <= 0x39)
            || char == 0x2b
            || char == 0x2f
            || char == 0x3d;
    }

    function _metadataLinkArrays(ID17LaunchFactory.Link[] calldata links)
        internal
        pure
        returns (string[] memory linkTypes, string[] memory linkUrls)
    {
        linkTypes = new string[](links.length);
        linkUrls = new string[](links.length);
        for (uint256 i; i < links.length; i++) {
            linkTypes[i] = links[i].linkType;
            linkUrls[i] = links[i].url;
        }
    }
}

project/contracts/D17FeeConfig.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice Protocol fee settings for FUTURE launches only.
///
/// What the owner can do:
///   - set the fee recipient and the fee rate, never above MAX_PROTOCOL_FEE_BPS (2%);
///   - hand over or renounce ownership (renouncing freezes the current settings forever).
/// What the owner can NOT do:
///   - touch any existing launch: D17Factory copies (recipient, rate) into each launch's
///     immutables at creation and they are part of that launch's rulesHash;
///   - move, pause or redirect any participant's funds: this contract holds nothing and
///     is only read by D17Factory.createLaunch.
/// The fee is charged only on successful settlement (a share of each settled commitment).
/// Refunds, refund penalties and failed launches never pay it.
contract D17FeeConfig {
    bytes32 public constant D17_FEE_CONFIG_ID = keccak256("D17_FEE_CONFIG_V15_HARDENED");
    uint16 public constant MAX_PROTOCOL_FEE_BPS = 200;

    address public owner;
    address public pendingOwner;
    address public feeRecipient;
    uint16 public protocolFeeBps;

    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event ProtocolFeeUpdated(address indexed feeRecipient, uint16 protocolFeeBps);

    modifier onlyOwner() {
        require(msg.sender == owner, "NOT_OWNER");
        _;
    }

    constructor(address owner_, address feeRecipient_, uint16 protocolFeeBps_) {
        require(owner_ != address(0), "OWNER_ZERO");
        owner = owner_;
        emit OwnershipTransferred(address(0), owner_);
        _setFee(feeRecipient_, protocolFeeBps_);
    }

    function setProtocolFee(address feeRecipient_, uint16 protocolFeeBps_) external onlyOwner {
        _setFee(feeRecipient_, protocolFeeBps_);
    }

    function currentFee() external view returns (address recipient, uint16 bps) {
        return (feeRecipient, protocolFeeBps);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner, newOwner);
    }

    function acceptOwnership() external {
        require(msg.sender == pendingOwner && msg.sender != address(0), "NOT_PENDING_OWNER");
        emit OwnershipTransferred(owner, msg.sender);
        owner = msg.sender;
        pendingOwner = address(0);
    }

    function renounceOwnership() external onlyOwner {
        emit OwnershipTransferred(owner, address(0));
        owner = address(0);
        pendingOwner = address(0);
    }

    function _setFee(address feeRecipient_, uint16 protocolFeeBps_) private {
        require(protocolFeeBps_ <= MAX_PROTOCOL_FEE_BPS, "FEE_ABOVE_CAP");
        require(protocolFeeBps_ == 0 || feeRecipient_ != address(0), "FEE_RECIPIENT_ZERO");
        feeRecipient = feeRecipient_;
        protocolFeeBps = protocolFeeBps_;
        emit ProtocolFeeUpdated(feeRecipient_, protocolFeeBps_);
    }
}

project/contracts/D17Launch.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {D17SafeTransfer} from "./lib/D17SafeTransfer.sol";
import {ID17FactoryView, IERC20BalanceView, IWETH} from "./interfaces/ID17.sol";

contract D17Launch {
    using D17SafeTransfer for address;

    bytes32 public constant D17_LAUNCH_ID = keccak256("D17_LAUNCH_V15_HARDENED");
    uint8 public constant ROUND_COUNT = 5;
    uint8 public constant FINAL_ROUND = 4;
    uint8 public constant REFUND_STAGE_COUNT = 4;
    // Contract rounds 0-1 refund at EARLY_REFUND_PENALTY_BPS, rounds 2-3 at the launch's
    // refundPenaltyBps; the final round has no normal refund window.
    uint8 public constant EARLY_REFUND_ROUNDS = 2;
    // Small fixed penalty on early refunds: makes "commit big, refund at the last second"
    // anchor griefing cost real money. Like every penalty it goes to the official pool
    // (or is burned if the launch fails), never to the creator or the protocol.
    uint16 public constant EARLY_REFUND_PENALTY_BPS = 100;
    uint8 public constant NO_ROUND = type(uint8).max;
    uint8 public constant PHASE_NOT_STARTED = 0;
    uint8 public constant PHASE_ROUND_OPEN = 1;
    uint8 public constant PHASE_REFUND_OPEN = 2;
    uint8 public constant PHASE_READY_TO_FINALIZE = 3;
    uint8 public constant PHASE_SETTLEMENT_OPEN = 4;
    uint8 public constant PHASE_POOL_READY = 5;
    uint8 public constant PHASE_TRADING_OPEN = 6;
    uint8 public constant PHASE_FAILED = 7;
    uint256 public constant BPS = 10_000;
    uint256 public constant MIN_COMMIT_WETH = 1e15;
    uint256 public constant MIN_LP_TOKENS = 1e18;
    uint256 public constant MIN_ROUND_ALLOCATION_TOKENS = 1e18;
    uint256 public constant MIN_ANCHOR_PRICE_WAD = 1e6;
    uint256 private constant WAD = 1e18;
    address public constant CANONICAL_DEAD_RECIPIENT = 0x000000000000000000000000000000000000dEaD;

    address public immutable factory;
    address public immutable vaultConfigurator;
    address public immutable token;
    address public immutable weth;
    address public immutable treasury;
    address public immutable protocolFeeRecipient;
    uint64 public immutable startTime;
    uint32 public immutable refundSeconds;
    uint32 public immutable settlementSeconds;
    uint256 public immutable tradingOpenAt;
    uint256 public immutable minCommitWeth;
    uint256 public immutable minPhase1Weth;
    uint256 public immutable minAnchorPriceWad;
    uint16 public immutable treasuryBps;
    uint16 public immutable protocolFeeBps;
    uint16 public immutable refundPenaltyBps;
    uint256 public immutable saleTokens;
    uint256 public immutable lpTokens;
    uint256 public immutable deadTokens;
    address public immutable deadRecipient;
    uint256 public immutable manualDistributionTokens;
    address public immutable manualDistributionRecipient;

    bytes32 public immutable metadataHash;

    address public liquidityVault;
    bool public liquidityPoolCreated;
    bool public vaultLiquidityClaimed;
    address public officialPair;
    uint256 public settledLiquidityWeth;
    uint256 public finalCommittedWeth;
    uint256 public settledCommittedWeth;
    uint256 public poolSettledLiquidityWeth;
    uint256 public poolSettledCommittedWeth;
    uint256 public lateSettledCommittedWeth;
    uint256 public lateSettledLiquidityWeth;
    uint256 public lateLpTokensReleased;
    uint256 public vaultLiquidityTokensClaimed;
    uint256 public officialTokenUsedForLp;
    uint256 public officialWethUsedForLp;
    uint256 public officialLpMinted;
    uint256 public poolCreatedAt;

    uint32[5] public roundSeconds;
    uint16[5] public roundSharesBps;
    uint256[5] public roundRaised;

    uint256 public retainedPenaltyWeth;
    uint256 public penaltyWethPaid;
    uint256 public treasuryWethPaid;
    uint256 public protocolFeeWethPaid;
    uint256 public unsoldSaleTokensSettled;
    uint256 public unusedLpTokensBurned;
    uint256 public effectiveLpTokens;
    uint256 public finalRoundTokenPool;
    bool public unsoldSaleTokensBurned;
    uint256 public finalizedAt;
    bool public finalized;
    uint256 private entered = 1;

    struct Position {
        bool finalSaleTokensClaimed;
        bool liquidityClaimed;
        uint256 refundWeth;
        uint256 penaltyWeth;
        uint256[5] paid;
        bool[5] refunded;
    }

    struct LaunchParams {
        address factory;
        address vaultConfigurator;
        address token;
        address weth;
        address treasury;
        address protocolFeeRecipient;
        bytes32 metadataHash;
        uint64 startTime;
        uint32[5] roundSeconds;
        uint32 refundSeconds;
        uint32 settlementSeconds;
        uint256 minCommitWeth;
        uint256 minPhase1Weth;
        uint256 minAnchorPriceWad;
        uint16[5] roundSharesBps;
        uint16 treasuryBps;
        uint16 protocolFeeBps;
        uint16 refundPenaltyBps;
        uint256 saleTokens;
        uint256 lpTokens;
        uint256 deadTokens;
        address deadRecipient;
        uint256 manualDistributionTokens;
        address manualDistributionRecipient;
    }

    mapping(address => Position) private positions;

    event LiquidityVaultConfigured(address indexed liquidityVault);
    event RoundCommitted(address indexed locker, uint8 indexed round, uint256 amount);
    event RoundRefunded(address indexed locker, uint8 indexed refundRound, uint256 refundWeth, uint256 penaltyWeth);
    event LaunchFailedRefunded(address indexed locker, uint256 refundWeth);
    event VaultSettlementClaimed(
        address indexed locker,
        uint256 saleTokens,
        uint256 wethForVault,
        uint256 treasuryWeth,
        uint256 protocolFeeWeth,
        uint256 grossCommittedWeth
    );
    event LateVaultSettlementClaimed(
        address indexed locker,
        uint256 saleTokens,
        uint256 wethForVault,
        uint256 treasuryWeth,
        uint256 protocolFeeWeth,
        uint256 lateLpTokens,
        uint256 grossCommittedWeth
    );
    event Finalized(uint256 finalizedAt);
    event VaultLiquidityTokensClaimed(
        address indexed liquidityVault,
        uint256 liquidityTokens,
        uint256 wethForPool
    );
    event LiquidityPoolCreated(
        address indexed liquidityVault,
        address indexed pair,
        uint256 tokenUsed,
        uint256 wethUsed,
        uint256 lpMinted
    );
    event UnsoldSaleTokensBurned(uint256 amount);
    event UnusedLpTokensBurned(uint256 amount);
    event ResidualTokensBurned(uint256 amount);
    event UnexpectedEthSwept(address indexed recipient, uint256 amount);

    modifier onlyLocker() {
        require(ID17FactoryView(factory).isLocker(msg.sender), "NOT_D17_LOCKER");
        _;
    }

    modifier onlyVault() {
        require(msg.sender == liquidityVault && liquidityVault != address(0), "NOT_LIQUIDITY_VAULT");
        _;
    }

    modifier nonReentrant() {
        require(entered == 1, "REENTRANT");
        entered = 2;
        _;
        entered = 1;
    }

    /// @dev Only D17LaunchDeployer (pinned to the canonical launch factory, which only the
    /// canonical D17Factory can drive after full config validation) creates launches, so the
    /// constructor keeps cheap structural checks; economic caps live in D17Factory.
    constructor(LaunchParams memory p) {
        require(p.factory != address(0), "FACTORY_ZERO");
        require(p.vaultConfigurator != address(0), "VAULT_CONFIG_ZERO");
        require(p.token != address(0), "TOKEN_ZERO");
        require(p.weth != address(0), "WETH_ZERO");
        require(p.treasury != address(0), "TREASURY_ZERO");
        require(p.protocolFeeBps == 0 || p.protocolFeeRecipient != address(0), "FEE_RECIPIENT_ZERO");
        require(uint256(p.treasuryBps) + p.protocolFeeBps < BPS, "FEE_BPS");
        require(p.refundPenaltyBps <= BPS, "REFUND_PENALTY_BPS");
        require(p.startTime >= block.timestamp, "START_PAST");
        require(p.refundSeconds > 0 && p.settlementSeconds > 0, "WINDOW_ZERO");
        require(p.minCommitWeth >= MIN_COMMIT_WETH, "MIN_COMMIT_TOO_LOW");
        require(p.minPhase1Weth >= p.minCommitWeth, "MIN_PHASE1_WETH");
        require(p.minAnchorPriceWad >= MIN_ANCHOR_PRICE_WAD, "MIN_ANCHOR_PRICE_TOO_LOW");
        require(p.saleTokens > 0, "SALE_ZERO");
        require(p.lpTokens >= MIN_LP_TOKENS, "LP_TOO_LOW");
        if (p.deadTokens > 0) require(p.deadRecipient == CANONICAL_DEAD_RECIPIENT, "DEAD_RECIPIENT");
        if (p.manualDistributionTokens > 0) {
            require(p.manualDistributionRecipient != address(0), "MANUAL_RECIPIENT_ZERO");
        }

        uint256 shareTotal;
        for (uint256 i; i < ROUND_COUNT; i++) {
            require(p.roundSeconds[i] > 0, "ROUND_SECONDS_ZERO");
            require(p.saleTokens * p.roundSharesBps[i] / BPS >= MIN_ROUND_ALLOCATION_TOKENS, "ROUND_ALLOCATION_TOO_LOW");
            roundSeconds[i] = p.roundSeconds[i];
            roundSharesBps[i] = p.roundSharesBps[i];
            shareTotal += p.roundSharesBps[i];
        }
        require(shareTotal == BPS, "ROUND_SHARE_TOTAL");

        factory = p.factory;
        vaultConfigurator = p.vaultConfigurator;
        token = p.token;
        weth = p.weth;
        treasury = p.treasury;
        protocolFeeRecipient = p.protocolFeeRecipient;
        metadataHash = p.metadataHash;
        startTime = p.startTime;
        refundSeconds = p.refundSeconds;
        settlementSeconds = p.settlementSeconds;
        tradingOpenAt = _roundEnd(ROUND_COUNT - 1, p.startTime, p.roundSeconds, p.refundSeconds) + p.settlementSeconds;
        minCommitWeth = p.minCommitWeth;
        minPhase1Weth = p.minPhase1Weth;
        minAnchorPriceWad = p.minAnchorPriceWad;
        treasuryBps = p.treasuryBps;
        protocolFeeBps = p.protocolFeeBps;
        refundPenaltyBps = p.refundPenaltyBps;
        saleTokens = p.saleTokens;
        lpTokens = p.lpTokens;
        deadTokens = p.deadTokens;
        deadRecipient = p.deadRecipient;
        manualDistributionTokens = p.manualDistributionTokens;
        manualDistributionRecipient = p.manualDistributionRecipient;
    }

    receive() external payable {
        revert("DIRECT_ETH_REJECTED");
    }

    fallback() external payable {
        revert("UNSUPPORTED_CALL");
    }

    function configureLiquidityVault(address liquidityVault_) external {
        require(msg.sender == vaultConfigurator, "NOT_VAULT_CONFIGURATOR");
        require(liquidityVault == address(0), "VAULT_CONFIGURED");
        require(liquidityVault_ != address(0), "VAULT_ZERO");
        require(liquidityVault_.code.length > 0, "VAULT_NO_CODE");
        liquidityVault = liquidityVault_;
        emit LiquidityVaultConfigured(liquidityVault_);
    }

    function rulesHash() public view returns (bytes32) {
        return keccak256(abi.encode(
            D17_LAUNCH_ID,
            factory,
            liquidityVault,
            token,
            weth,
            treasury,
            protocolFeeRecipient,
            startTime,
            refundSeconds,
            settlementSeconds,
            tradingOpenAt,
            minCommitWeth,
            minPhase1Weth,
            minAnchorPriceWad,
            roundSeconds,
            roundSharesBps,
            treasuryBps,
            protocolFeeBps,
            refundPenaltyBps,
            saleTokens,
            lpTokens,
            deadTokens,
            deadRecipient,
            manualDistributionTokens,
            manualDistributionRecipient,
            metadataHash
        ));
    }

    function activeRound() public view returns (uint8) {
        for (uint8 round; round < ROUND_COUNT; round++) {
            uint256 start = roundStart(round);
            if (block.timestamp >= start && block.timestamp < start + roundSeconds[round]) {
                if (round > 0 && !anchorReady()) return NO_ROUND;
                return round;
            }
        }
        return NO_ROUND;
    }

    function activeRefundWindow() public view returns (uint8) {
        for (uint8 round; round < REFUND_STAGE_COUNT; round++) {
            uint256 end = roundEnd(round);
            if (block.timestamp >= end && block.timestamp < end + refundSeconds) return round;
        }
        return NO_ROUND;
    }

    function roundStart(uint8 round) public view returns (uint256) {
        require(round < ROUND_COUNT, "ROUND");
        uint256 cursor = startTime;
        for (uint8 i; i < round; i++) {
            cursor += roundSeconds[i];
            if (i < REFUND_STAGE_COUNT) cursor += refundSeconds;
        }
        return cursor;
    }

    function roundEnd(uint8 round) public view returns (uint256) {
        return roundStart(round) + roundSeconds[round];
    }

    function roundBaseTokenAllocation(uint8 round) public view returns (uint256) {
        require(round < ROUND_COUNT, "ROUND");
        return saleTokens * roundSharesBps[round] / BPS;
    }

    function roundTokenAllocation(uint8 round) public view returns (uint256) {
        require(round < ROUND_COUNT, "ROUND");
        if (round == FINAL_ROUND) {
            return finalized ? finalRoundTokenPool : roundBaseTokenAllocation(FINAL_ROUND) + rolloverToFinalRound();
        }
        return roundBaseTokenAllocation(round);
    }

    function roundClaimTime(uint8 round) public view returns (uint256) {
        require(round < ROUND_COUNT, "ROUND");
        if (round < REFUND_STAGE_COUNT) return roundEnd(round) + refundSeconds;
        return roundEnd(round);
    }

    function anchorPriceWad() public view returns (uint256) {
        uint256 allocation = roundBaseTokenAllocation(0);
        if (allocation == 0 || roundRaised[0] == 0) return 0;
        return roundRaised[0] * WAD / allocation;
    }

    function anchorReady() public view returns (bool) {
        return roundRaised[0] >= minPhase1Weth && anchorPriceWad() >= minAnchorPriceWad;
    }

    function launchFailed() public view returns (bool) {
        return !finalized && block.timestamp >= roundEnd(0) + refundSeconds && !anchorReady();
    }

    /// @notice WETH needed for a round to sell its whole allocation at the phase-one anchor
    /// price. Applies to rounds 1-3 and, since V15, to the final round too: no round ever
    /// sells below the anchor price; the unsold remainder is burned at finalization.
    function roundAnchorTargetWeth(uint8 round) public view returns (uint256) {
        require(round < ROUND_COUNT, "ROUND");
        if (round == 0) return 0;
        return roundTokenAllocation(round) * anchorPriceWad() / WAD;
    }

    function roundAnchorUnderfillRemainingWeth(uint8 round) public view returns (uint256) {
        uint256 target = roundAnchorTargetWeth(round);
        if (roundRaised[round] >= target) return 0;
        return target - roundRaised[round];
    }

    function roundSoldTokens(uint8 round) public view returns (uint256) {
        require(round < ROUND_COUNT, "ROUND");
        uint256 raised = roundRaised[round];
        if (raised == 0) return 0;
        uint256 allocation = roundTokenAllocation(round);
        if (round == 0) return anchorReady() ? allocation : 0;

        uint256 target = roundAnchorTargetWeth(round);
        if (target == 0) return 0;
        if (raised >= target) return allocation;
        return allocation * raised / target;
    }

    function rolloverToFinalRound() public view returns (uint256 rolloverTokens) {
        for (uint8 round = 1; round < FINAL_ROUND; round++) {
            uint256 allocation = roundBaseTokenAllocation(round);
            uint256 sold = roundSoldTokens(round);
            if (allocation > sold) rolloverTokens += allocation - sold;
        }
    }

    function roundDiscoveredPriceWad(uint8 round) public view returns (uint256) {
        uint256 soldTokens = roundSoldTokens(round);
        if (soldTokens == 0) return 0;
        return roundRaised[round] * WAD / soldTokens;
    }

    function isRoundClaimable(uint8 round) public view returns (bool) {
        return block.timestamp >= roundClaimTime(round);
    }

    function settlementStartsAt() public view returns (uint256) {
        return roundEnd(FINAL_ROUND);
    }

    function poolCreationOpensAt() public view returns (uint256) {
        if (!finalized) return tradingOpenAt;
        uint256 finalizedDeadline = finalizedAt + settlementSeconds;
        return finalizedDeadline > tradingOpenAt ? finalizedDeadline : tradingOpenAt;
    }

    function tradingOpen() public view returns (bool) {
        return liquidityPoolCreated;
    }

    function totalCommittedWeth() public view returns (uint256 total) {
        for (uint8 round; round < ROUND_COUNT; round++) total += roundRaised[round];
    }

    /// @notice Share of every successful commitment that goes to the official pool.
    function liquidityBps() public view returns (uint256) {
        return BPS - treasuryBps - protocolFeeBps;
    }

    /// @notice Canonical pool WETH: the liquidity share of every final commitment plus all
    /// refund penalties (which are paid into the vault and paired at pool creation).
    function totalLiquidityWeth() public view returns (uint256) {
        uint256 committed = finalized ? finalCommittedWeth : totalCommittedWeth();
        return committed * liquidityBps() / BPS + retainedPenaltyWeth;
    }

    /// @notice LP tokens that will pair with totalLiquidityWeth(). Scaled to the share of the
    /// sale that actually sold, so the opening price tracks the average sale price (equal to
    /// it net of fees when lpTokens == saleTokens) instead of being set by an unsold
    /// allocation; the unused part is burned at finalization.
    function poolTokenAllocation() public view returns (uint256) {
        if (finalized) return effectiveLpTokens;
        return lpTokens * _soldSaleTokenAmount() / saleTokens;
    }

    /// @notice Read-only settlement-progress metric; it never gates lifecycle progress.
    function allFinalCommitmentsSettled() public view returns (bool) {
        return finalized && finalCommittedWeth > 0 && settledCommittedWeth == finalCommittedWeth;
    }

    function contributedBy(address locker, uint8 round) external view returns (uint256) {
        require(round < ROUND_COUNT, "ROUND");
        return positions[locker].paid[round];
    }

    function lockerPositionState(address locker)
        external
        view
        returns (
            bool liquidityClaimed,
            bool finalSaleTokensClaimed,
            uint256 refundWeth,
            uint256 penaltyWeth,
            bool[5] memory refunded
        )
    {
        Position storage position = positions[locker];
        return (
            position.liquidityClaimed,
            position.finalSaleTokensClaimed,
            position.refundWeth,
            position.penaltyWeth,
            position.refunded
        );
    }

    function previewRoundTokens(address locker, uint8 round) public view returns (uint256 saleTokenAmount) {
        require(round < ROUND_COUNT, "ROUND");
        Position storage position = positions[locker];
        if (position.finalSaleTokensClaimed || position.refunded[round]) return 0;
        uint256 paid = position.paid[round];
        if (paid == 0) return 0;
        return _roundTokensForBuyer(round, paid);
    }

    function previewFinalSaleTokens(address locker) public view returns (uint256 saleTokenAmount) {
        Position storage position = positions[locker];
        if (position.finalSaleTokensClaimed) return 0;
        for (uint8 round; round < ROUND_COUNT; round++) saleTokenAmount += previewRoundTokens(locker, round);
    }

    function previewVaultSettlement(address locker)
        public
        view
        returns (
            uint256 saleTokenAmount,
            uint256 grossCommittedWeth,
            uint256 wethForVault,
            uint256 treasuryWeth,
            uint256 protocolFeeWeth
        )
    {
        Position storage position = positions[locker];
        if (position.liquidityClaimed) return (0, 0, 0, 0, 0);
        saleTokenAmount = previewFinalSaleTokens(locker);
        (grossCommittedWeth, wethForVault, treasuryWeth, protocolFeeWeth) = _vaultSettlementAmounts(position);
    }

    function launchPhase()
        external
        view
        returns (uint8 phaseKind, uint8 index, uint256 startsAt, uint256 endsAt)
    {
        if (finalized && liquidityPoolCreated) {
            return (PHASE_TRADING_OPEN, NO_ROUND, poolCreatedAt, type(uint256).max);
        }
        if (finalized && block.timestamp < poolCreationOpensAt()) {
            return (PHASE_SETTLEMENT_OPEN, NO_ROUND, finalizedAt, poolCreationOpensAt());
        }
        if (finalized) {
            return (PHASE_POOL_READY, NO_ROUND, poolCreationOpensAt(), type(uint256).max);
        }
        if (block.timestamp < startTime) return (PHASE_NOT_STARTED, NO_ROUND, startTime, startTime);
        if (launchFailed()) return (PHASE_FAILED, NO_ROUND, roundEnd(0) + refundSeconds, type(uint256).max);

        uint8 round = activeRound();
        if (round != NO_ROUND) return (PHASE_ROUND_OPEN, round, roundStart(round), roundEnd(round));

        uint8 refundWindow = activeRefundWindow();
        if (refundWindow != NO_ROUND) {
            uint256 refundStart = roundEnd(refundWindow);
            return (PHASE_REFUND_OPEN, refundWindow, refundStart, refundStart + refundSeconds);
        }

        if (block.timestamp >= roundEnd(ROUND_COUNT - 1)) {
            uint256 finalRoundEnd = roundEnd(ROUND_COUNT - 1);
            return (PHASE_READY_TO_FINALIZE, NO_ROUND, finalRoundEnd, poolCreationOpensAt());
        }

        return (PHASE_NOT_STARTED, NO_ROUND, startTime, startTime);
    }

    function recordRoundCommitment(uint8 round, uint256 amount) external onlyLocker nonReentrant {
        require(round < ROUND_COUNT, "ROUND");
        require(amount >= minCommitWeth, "COMMIT_TOO_SMALL");
        require(round == activeRound(), "ROUND_CLOSED");
        if (round > 0) require(anchorReady(), "ANCHOR_NOT_READY");

        Position storage position = positions[msg.sender];
        require(!position.liquidityClaimed, "LIQUIDITY_CLAIMED");
        require(!position.refunded[round], "ROUND_REFUNDED");
        require(!position.finalSaleTokensClaimed, "SALE_TOKENS_CLAIMED");

        position.paid[round] += amount;
        roundRaised[round] += amount;
        emit RoundCommitted(msg.sender, round, amount);
    }

    function releaseRoundRefund()
        external
        onlyLocker
        nonReentrant
        returns (uint8 round, uint256 refundWeth, uint256 penaltyWeth)
    {
        round = activeRefundWindow();
        require(round != NO_ROUND, "NO_REFUND_STAGE");

        Position storage position = positions[msg.sender];
        require(!position.liquidityClaimed, "LIQUIDITY_CLAIMED");
        require(!position.refunded[round], "ROUND_REFUNDED");
        require(!position.finalSaleTokensClaimed, "SALE_TOKENS_CLAIMED");

        uint256 gross = position.paid[round];
        require(gross > 0, "NO_ROUND_POSITION");

        roundRaised[round] -= gross;
        position.paid[round] = 0;
        position.refunded[round] = true;

        // Refund schedule [early, early, launch, launch, no-window]. The locker pays the
        // penalty into the liquidity vault: it deepens the official pool (or is burned if
        // the launch fails). Neither the creator's treasury nor the protocol receives it.
        penaltyWeth = gross * (round < EARLY_REFUND_ROUNDS ? EARLY_REFUND_PENALTY_BPS : refundPenaltyBps) / BPS;
        refundWeth = gross - penaltyWeth;
        retainedPenaltyWeth += penaltyWeth;
        penaltyWethPaid += penaltyWeth;
        position.refundWeth += refundWeth;
        position.penaltyWeth += penaltyWeth;

        emit RoundRefunded(msg.sender, round, refundWeth, penaltyWeth);
    }

    function releaseFailedRefund() external onlyLocker nonReentrant returns (uint256 refundWeth) {
        require(launchFailed(), "LAUNCH_NOT_FAILED");

        Position storage position = positions[msg.sender];
        require(!position.liquidityClaimed, "LIQUIDITY_CLAIMED");
        require(!position.finalSaleTokensClaimed, "SALE_TOKENS_CLAIMED");

        for (uint8 round; round < ROUND_COUNT; round++) {
            uint256 paid = position.paid[round];
            if (paid == 0) continue;
            roundRaised[round] -= paid;
            position.paid[round] = 0;
            position.refunded[round] = true;
            refundWeth += paid;
        }

        require(refundWeth > 0, "NO_POSITION");
        position.refundWeth += refundWeth;
        emit LaunchFailedRefunded(msg.sender, refundWeth);
    }

    function claimVaultSettlement()
        external
        onlyLocker
        nonReentrant
        returns (uint256 saleTokenAmount, uint256 wethForVault, uint256 treasuryWeth, uint256 protocolFeeWeth)
    {
        require(!liquidityPoolCreated, "POOL_CREATED");
        (saleTokenAmount, wethForVault, treasuryWeth, protocolFeeWeth, ) = _settlePosition(false);
    }

    /// @notice Settlement for lockers that missed pool creation: the exact finalized sale
    /// tokens for the exact same WETH cost and fees. The position's LP-share WETH and its
    /// share of the reserved LP tokens are sent to the vault, which adds them to the official
    /// pair at the pair's current ratio in the same transaction. Callable forever.
    function claimLateSettlement()
        external
        onlyLocker
        nonReentrant
        returns (
            uint256 saleTokenAmount,
            uint256 wethForVault,
            uint256 treasuryWeth,
            uint256 protocolFeeWeth,
            uint256 lateLpTokens
        )
    {
        require(liquidityPoolCreated, "POOL_NOT_CREATED");
        return _settlePosition(true);
    }

    function _settlePosition(bool late)
        internal
        returns (
            uint256 saleTokenAmount,
            uint256 wethForVault,
            uint256 treasuryWeth,
            uint256 protocolFeeWeth,
            uint256 lateLpTokens
        )
    {
        require(liquidityVault != address(0), "VAULT_NOT_CONFIGURED");
        if (!finalized) _finalizeLaunch();

        Position storage position = positions[msg.sender];
        require(!position.liquidityClaimed, "LIQUIDITY_CLAIMED");
        require(!position.finalSaleTokensClaimed, "SALE_TOKENS_CLAIMED");
        saleTokenAmount = previewFinalSaleTokens(msg.sender);
        uint256 grossCommittedWeth;
        (grossCommittedWeth, wethForVault, treasuryWeth, protocolFeeWeth) = _vaultSettlementAmounts(position);
        require(grossCommittedWeth > 0, "NO_POSITION");

        position.liquidityClaimed = true;
        position.finalSaleTokensClaimed = true;
        settledCommittedWeth += grossCommittedWeth;
        treasuryWethPaid += treasuryWeth;
        protocolFeeWethPaid += protocolFeeWeth;

        if (late) {
            // Per-position fee rounding means the per-position liquidity shares can sum to a
            // few wei above totalLiquidityWeth(); capping at the remaining reserve keeps the
            // last late settler from ever being blocked by that rounding.
            uint256 reserve = effectiveLpTokens - vaultLiquidityTokensClaimed - lateLpTokensReleased;
            lateLpTokens = effectiveLpTokens * wethForVault / totalLiquidityWeth();
            if (lateLpTokens > reserve) lateLpTokens = reserve;
            lateSettledCommittedWeth += grossCommittedWeth;
            lateSettledLiquidityWeth += wethForVault;
            lateLpTokensReleased += lateLpTokens;
            if (lateLpTokens > 0) token.safeTransfer(liquidityVault, lateLpTokens);
            emit LateVaultSettlementClaimed(
                msg.sender,
                saleTokenAmount,
                wethForVault,
                treasuryWeth,
                protocolFeeWeth,
                lateLpTokens,
                grossCommittedWeth
            );
        } else {
            settledLiquidityWeth += wethForVault;
            emit VaultSettlementClaimed(
                msg.sender, saleTokenAmount, wethForVault, treasuryWeth, protocolFeeWeth, grossCommittedWeth
            );
        }

        if (saleTokenAmount > 0) token.safeTransfer(msg.sender, saleTokenAmount);
    }

    function finalizeLaunch() external nonReentrant {
        _finalizeLaunch();
    }

    function claimVaultLiquidityTokens()
        external
        onlyVault
        nonReentrant
        returns (uint256 liquidityTokens, uint256 wethForPool)
    {
        if (!finalized) _finalizeLaunch();
        require(!liquidityPoolCreated, "POOL_CREATED");
        require(!vaultLiquidityClaimed, "VAULT_LIQUIDITY_CLAIMED");
        require(block.timestamp >= poolCreationOpensAt(), "POOL_CREATION_NOT_OPEN");
        require(settledLiquidityWeth > 0, "NO_SETTLED_LIQUIDITY");

        // The initial pool pairs the settled WETH plus every refund penalty with the
        // proportional share of the LP token allocation, so it opens at the canonical ratio
        // (poolTokenAllocation : totalLiquidityWeth). The rest stays reserved for late settlers.
        wethForPool = settledLiquidityWeth + retainedPenaltyWeth;
        liquidityTokens = effectiveLpTokens * wethForPool / totalLiquidityWeth();
        require(liquidityTokens > 0, "NO_LIQUIDITY_TOKENS");

        vaultLiquidityClaimed = true;
        vaultLiquidityTokensClaimed = liquidityTokens;
        poolSettledLiquidityWeth = settledLiquidityWeth;
        poolSettledCommittedWeth = settledCommittedWeth;
        token.safeTransfer(liquidityVault, liquidityTokens);

        emit VaultLiquidityTokensClaimed(liquidityVault, liquidityTokens, wethForPool);
    }

    function markLiquidityPoolCreated(address pair, uint256 tokenUsed, uint256 wethUsed, uint256 lpMinted)
        external
        onlyVault
        nonReentrant
    {
        require(!liquidityPoolCreated, "POOL_CREATED");
        require(vaultLiquidityClaimed, "VAULT_LIQUIDITY_NOT_CLAIMED");
        require(pair != address(0), "PAIR_ZERO");
        require(tokenUsed == vaultLiquidityTokensClaimed, "TOKEN_USED_MISMATCH");
        require(wethUsed == poolSettledLiquidityWeth + retainedPenaltyWeth, "WETH_USED_MISMATCH");
        require(lpMinted > 0, "LP_ZERO");

        liquidityPoolCreated = true;
        officialPair = pair;
        officialTokenUsedForLp = tokenUsed;
        officialWethUsedForLp = wethUsed;
        officialLpMinted = lpMinted;
        poolCreatedAt = block.timestamp;

        emit LiquidityPoolCreated(liquidityVault, pair, tokenUsed, wethUsed, lpMinted);
    }

    /// @notice Once every final commitment has settled, whatever the launch still holds is
    /// per-position rounding dust (sale and reserved LP tokens). Anyone may burn it.
    function burnResidualTokens() external nonReentrant returns (uint256 amount) {
        require(liquidityPoolCreated && allFinalCommitmentsSettled(), "SETTLEMENT_OPEN");
        amount = IERC20BalanceView(token).balanceOf(address(this));
        require(amount > 0, "NO_RESIDUAL");
        token.safeBurn(amount);
        emit ResidualTokensBurned(amount);
    }

    /// @notice Forced ETH (selfdestruct / coinbase) is wrapped and sent as WETH, so a
    /// treasury that rejects ETH cannot block the sweep.
    function sweepUnexpectedEthToTreasury() external nonReentrant returns (uint256 amount) {
        amount = address(this).balance;
        require(amount > 0, "NO_ETH_BALANCE");
        IWETH(weth).deposit{value: amount}();
        weth.safeTransfer(treasury, amount);
        emit UnexpectedEthSwept(treasury, amount);
    }

    function _finalizeLaunch() internal {
        require(!finalized, "FINALIZED");
        require(!launchFailed(), "LAUNCH_FAILED");
        require(block.timestamp >= roundEnd(ROUND_COUNT - 1), "NOT_OVER");

        finalized = true;
        finalizedAt = block.timestamp;
        finalRoundTokenPool = roundBaseTokenAllocation(FINAL_ROUND) + rolloverToFinalRound();
        finalCommittedWeth = totalCommittedWeth();
        // Canonical launches only reach finalization after the phase-one anchor made total
        // commitments nonzero; keep the explicit guard against finalizing an empty launch.
        require(finalCommittedWeth > 0, "NO_FINAL_COMMITMENTS");

        uint256 soldSaleTokens = _soldSaleTokenAmount();
        unsoldSaleTokensSettled = saleTokens - soldSaleTokens;
        effectiveLpTokens = lpTokens * soldSaleTokens / saleTokens;
        unusedLpTokensBurned = lpTokens - effectiveLpTokens;

        // Unsold sale tokens and the unused LP allocation are always burned: no wallet,
        // including the creator's treasury, ever receives tokens the market did not buy.
        if (unsoldSaleTokensSettled + unusedLpTokensBurned > 0) {
            token.safeBurn(unsoldSaleTokensSettled + unusedLpTokensBurned);
        }
        if (unsoldSaleTokensSettled > 0) {
            unsoldSaleTokensBurned = true;
            emit UnsoldSaleTokensBurned(unsoldSaleTokensSettled);
        }
        if (unusedLpTokensBurned > 0) emit UnusedLpTokensBurned(unusedLpTokensBurned);

        emit Finalized(finalizedAt);
    }

    function _vaultSettlementAmounts(Position storage position)
        internal
        view
        returns (uint256 grossCommittedWeth, uint256 wethForVault, uint256 treasuryWeth, uint256 protocolFeeWeth)
    {
        for (uint8 round; round < ROUND_COUNT; round++) grossCommittedWeth += position.paid[round];
        if (grossCommittedWeth == 0) return (0, 0, 0, 0);

        treasuryWeth = grossCommittedWeth * treasuryBps / BPS;
        protocolFeeWeth = grossCommittedWeth * protocolFeeBps / BPS;
        wethForVault = grossCommittedWeth - treasuryWeth - protocolFeeWeth;
    }

    function _roundTokensForBuyer(uint8 round, uint256 paid) internal view returns (uint256) {
        if (paid == 0) return 0;
        if (roundRaised[round] == 0) return 0;
        if (round == 0) {
            if (!anchorReady()) return 0;
            return roundBaseTokenAllocation(0) * paid / roundRaised[round];
        }

        uint256 sold = roundSoldTokens(round);
        if (sold == 0) return 0;
        return sold * paid / roundRaised[round];
    }

    function _soldSaleTokenAmount() internal view returns (uint256 soldSaleTokens) {
        for (uint8 round; round < ROUND_COUNT; round++) soldSaleTokens += roundSoldTokens(round);
        if (soldSaleTokens > saleTokens) return saleTokens;
    }

    function _roundEnd(uint8 round, uint256 start, uint32[5] memory durations, uint32 refundDuration)
        private
        pure
        returns (uint256)
    {
        uint256 cursor = start;
        for (uint8 i; i < round; i++) {
            cursor += durations[i];
            if (i < REFUND_STAGE_COUNT) cursor += refundDuration;
        }
        return cursor + durations[round];
    }
}

project/contracts/D17LaunchDeployer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {D17Launch} from "./D17Launch.sol";

/// @notice Deploys D17Launch instances for the pinned D17LaunchFactory. Split out of the
/// launch factory so that the launch's creation code no longer counts against the
/// launch factory's EIP-170 runtime size limit. Same owner-pin-renounce lifecycle as
/// D17TokenFactory and D17LiquidityVaultFactory.
contract D17LaunchDeployer {
    bytes32 public constant D17_LAUNCH_DEPLOYER_ID = keccak256("D17_LAUNCH_DEPLOYER_V15_HARDENED");

    address public owner;
    address public launchFactory;
    bool public launchFactoryPinned;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event LaunchFactoryPinned(address indexed launchFactory);
    event LaunchDeployed(address indexed launch);

    modifier onlyOwner() {
        require(msg.sender == owner, "NOT_OWNER");
        _;
    }

    constructor(address owner_) {
        require(owner_ != address(0), "OWNER_ZERO");
        owner = owner_;
        emit OwnershipTransferred(address(0), owner_);
    }

    function pinLaunchFactory(address launchFactory_) external onlyOwner {
        require(!launchFactoryPinned, "LAUNCH_FACTORY_PINNED");
        require(launchFactory_ != address(0), "LAUNCH_FACTORY_ZERO");
        require(launchFactory_.code.length > 0, "LAUNCH_FACTORY_NO_CODE");
        launchFactory = launchFactory_;
        launchFactoryPinned = true;
        emit LaunchFactoryPinned(launchFactory_);
    }

    function renounceOwnership() external onlyOwner {
        require(launchFactoryPinned, "LAUNCH_FACTORY_UNLOCKED");
        emit OwnershipTransferred(owner, address(0));
        owner = address(0);
    }

    /// @param encodedParams abi.encode(D17Launch.LaunchParams). Passed pre-encoded so this
    /// contract stays a thin wrapper around the launch creation code.
    /// @dev The calling launch factory must be the launch's one-shot vault configurator
    /// (second static word of the encoded params).
    function deployLaunch(bytes calldata encodedParams) external returns (address launch) {
        require(launchFactoryPinned && msg.sender == launchFactory, "NOT_LAUNCH_FACTORY");
        require(abi.decode(encodedParams[32:64], (address)) == msg.sender, "VAULT_CONFIGURATOR");
        bytes memory initCode = abi.encodePacked(type(D17Launch).creationCode, encodedParams);
        assembly ("memory-safe") {
            launch := create(0, add(initCode, 0x20), mload(initCode))
        }
        require(launch != address(0), "LAUNCH_DEPLOY_FAILED");
        emit LaunchDeployed(launch);
    }
}

project/contracts/D17LaunchFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {D17Launch} from "./D17Launch.sol";

interface ID17LaunchDeployer {
    function deployLaunch(bytes calldata encodedParams) external returns (address launch);
}
import {ID17LaunchFactory} from "./interfaces/ID17LaunchFactory.sol";

interface ID17FactoryConfigView {
    function weth() external view returns (address);
    function router() external view returns (address);
}

interface IV2RouterFactoryView {
    function factory() external view returns (address);
}

interface ID17LiquidityVaultFactory {
    function deployVault(address launch, address token, address weth, address router, address treasury)
        external
        returns (address liquidityVault);
}

interface ID17OwnedFactory {
    function owner() external view returns (address);
}

interface ID17TokenFactory {
    function deployToken(address tokenOwner, string calldata name, string calldata symbol, uint256 maxSupply)
        external
        returns (address token);
}

interface ID17LaunchToken {
    function configureTradingGate(
        address launch,
        address d17Factory,
        address weth,
        address routerFactory,
        address liquidityVault,
        uint256 tradingOpenAt
    ) external;
    function configureMetadata(
        string calldata description,
        string calldata logoSvgUri,
        ID17LaunchFactory.Link[] calldata links
    ) external;
    function mint(address to, uint256 amount) external;
    function closeMinting() external;
    function renounceOwnership() external;
}

contract D17LaunchFactory is ID17LaunchFactory {
    address public constant CANONICAL_DEAD_RECIPIENT = 0x000000000000000000000000000000000000dEaD;

    address public immutable d17Factory;
    address public immutable tokenFactory;
    address public immutable liquidityVaultFactory;
    address public immutable launchDeployer;

    modifier onlyD17Factory() {
        require(msg.sender == d17Factory, "NOT_D17_FACTORY");
        _;
    }

    constructor(address d17Factory_, address tokenFactory_, address liquidityVaultFactory_, address launchDeployer_) {
        require(d17Factory_ != address(0), "FACTORY_ZERO");
        require(tokenFactory_ != address(0), "TOKEN_FACTORY_ZERO");
        require(liquidityVaultFactory_ != address(0), "VAULT_FACTORY_ZERO");
        require(d17Factory_.code.length > 0, "FACTORY_NO_CODE");
        require(tokenFactory_.code.length > 0, "TOKEN_FACTORY_NO_CODE");
        require(liquidityVaultFactory_.code.length > 0, "VAULT_FACTORY_NO_CODE");
        require(launchDeployer_ != address(0), "LAUNCH_DEPLOYER_ZERO");
        require(launchDeployer_.code.length > 0, "LAUNCH_DEPLOYER_NO_CODE");
        d17Factory = d17Factory_;
        launchDeployer = launchDeployer_;
        tokenFactory = tokenFactory_;
        liquidityVaultFactory = liquidityVaultFactory_;
    }

    function deployLaunch(
        LaunchConfig calldata config,
        address creator,
        address protocolFeeRecipient,
        uint16 protocolFeeBps
    )
        external
        onlyD17Factory
        returns (address token, address launch, address liquidityVault)
    {
        require(creator != address(0), "CREATOR_ZERO");
        // Every contract in the creation path must be admin-free before any launch exists.
        require(
            ID17OwnedFactory(tokenFactory).owner() == address(0)
                && ID17OwnedFactory(liquidityVaultFactory).owner() == address(0)
                && ID17OwnedFactory(launchDeployer).owner() == address(0),
            "FACTORIES_NOT_RENOUNCED"
        );
        token = ID17TokenFactory(tokenFactory).deployToken(
            address(this),
            config.tokenName,
            config.tokenSymbol,
            config.tokenSupply
        );

        address weth = ID17FactoryConfigView(d17Factory).weth();
        D17Launch deployedLaunch = D17Launch(payable(ID17LaunchDeployer(launchDeployer).deployLaunch(abi.encode(
            D17Launch.LaunchParams({
                factory: d17Factory,
                vaultConfigurator: address(this),
                token: token,
                weth: weth,
                treasury: config.treasury,
                protocolFeeRecipient: protocolFeeRecipient,
                metadataHash: _metadataHash(config),
                startTime: config.startTime,
                roundSeconds: config.roundSeconds,
                refundSeconds: config.refundSeconds,
                settlementSeconds: config.settlementSeconds,
                minCommitWeth: config.minCommitWeth,
                minPhase1Weth: config.minPhase1Weth,
                minAnchorPriceWad: config.minAnchorPriceWad,
                roundSharesBps: config.roundSharesBps,
                treasuryBps: config.treasuryBps,
                protocolFeeBps: protocolFeeBps,
                refundPenaltyBps: config.refundPenaltyBps,
                saleTokens: config.saleTokens,
                lpTokens: config.lpTokens,
                deadTokens: config.deadTokens,
                deadRecipient: config.deadRecipient,
                manualDistributionTokens: config.manualDistributionTokens,
                manualDistributionRecipient: creator
            })
        ))));
        launch = address(deployedLaunch);

        address router = ID17FactoryConfigView(d17Factory).router();
        address routerFactory = IV2RouterFactoryView(router).factory();
        liquidityVault =
            ID17LiquidityVaultFactory(liquidityVaultFactory).deployVault(launch, token, weth, router, config.treasury);

        deployedLaunch.configureLiquidityVault(liquidityVault);
        ID17LaunchToken(token).configureTradingGate(
            launch,
            d17Factory,
            weth,
            routerFactory,
            liquidityVault,
            deployedLaunch.tradingOpenAt()
        );
        ID17LaunchToken(token).configureMetadata(config.description, config.logoSvgUri, config.links);

        ID17LaunchToken(token).mint(launch, config.saleTokens + config.lpTokens);
        // The creator allocation is minted into the liquidity vault, which vests it to the
        // creator linearly after the official pool opens (no day-one dump).
        if (config.manualDistributionTokens > 0) {
            ID17LaunchToken(token).mint(liquidityVault, config.manualDistributionTokens);
        }
        if (config.deadTokens > 0) ID17LaunchToken(token).mint(CANONICAL_DEAD_RECIPIENT, config.deadTokens);
        ID17LaunchToken(token).closeMinting();
        ID17LaunchToken(token).renounceOwnership();
    }

    function _metadataHash(LaunchConfig calldata config) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                config.tokenName,
                config.tokenSymbol,
                config.description,
                config.logoSvgUri,
                config.links
            )
        );
    }
}

project/contracts/D17LiquidityVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {D17SafeTransfer} from "./lib/D17SafeTransfer.sol";
import {ID17FactoryView, ID17Launch, IERC20BalanceView, IV2Factory, IV2PairView, IV2Router, IWETH} from "./interfaces/ID17.sol";

/// @notice Owns the official pair's LP forever (there is no LP withdrawal path), pairs the
/// launch's liquidity WETH and refund penalties with the LP token share, adds late settlers'
/// liquidity at the pair's live ratio, and vests the creator allocation.
contract D17LiquidityVault {
    using D17SafeTransfer for address;

    bytes32 public constant D17_LIQUIDITY_VAULT_ID = keccak256("D17_LIQUIDITY_VAULT_V15_HARDENED");
    /// @notice The creator allocation unlocks linearly over this period, starting when the
    /// official pool is created (= when trading opens).
    uint256 public constant CREATOR_VESTING_SECONDS = 180 days;
    address public constant BURN_ADDRESS = 0x000000000000000000000000000000000000dEaD;

    address public immutable launch;
    address public immutable token;
    address public immutable weth;
    address public immutable router;
    address public immutable routerFactory;
    address public immutable treasury;

    bool public poolCreated;
    address public officialPair;
    uint256 public poolCreatedAt;
    uint256 public tokenUsedForPool;
    uint256 public wethUsedForPool;
    uint256 public lpMinted;
    uint256 public lateTokenUsedForLp;
    uint256 public lateWethUsedForLp;
    uint256 public lateLpMinted;
    uint256 public lateTokensBurned;
    uint256 public lateWethBurned;
    uint256 public failedLaunchPenaltyWethBurned;
    uint256 public creatorTokensReleased;
    uint256 public preseededTokenReserve;
    uint256 public preseededWethReserve;
    uint256 private entered = 1;

    event OfficialPoolCreated(
        address indexed pair,
        uint256 tokenUsed,
        uint256 wethUsed,
        uint256 lpMinted,
        uint256 preseededTokenReserve,
        uint256 preseededWethReserve
    );
    event LateLiquidityAdded(
        address indexed locker,
        address indexed pair,
        uint256 tokenUsed,
        uint256 wethUsed,
        uint256 lpMinted,
        uint256 tokensBurned,
        uint256 wethBurned
    );
    event FailedLaunchPenaltiesBurned(uint256 amount);
    event CreatorTokensReleased(address indexed recipient, uint256 amount);
    event ExcessWethSwept(address indexed recipient, uint256 amount);
    event UnsupportedTokenRecovered(address indexed token, address indexed recipient, uint256 amount);
    event UnexpectedEthSwept(address indexed recipient, uint256 amount);

    modifier nonReentrant() {
        require(entered == 1, "REENTRANT");
        entered = 2;
        _;
        entered = 1;
    }

    constructor(address launch_, address token_, address weth_, address router_, address treasury_) {
        require(launch_ != address(0), "LAUNCH_ZERO");
        require(token_ != address(0), "TOKEN_ZERO");
        require(weth_ != address(0), "WETH_ZERO");
        require(router_ != address(0), "ROUTER_ZERO");
        require(treasury_ != address(0), "TREASURY_ZERO");
        require(launch_.code.length > 0, "LAUNCH_NO_CODE");
        require(token_.code.length > 0, "TOKEN_NO_CODE");
        require(weth_.code.length > 0, "WETH_NO_CODE");
        require(router_.code.length > 0, "ROUTER_NO_CODE");

        address routerFactory_ = IV2Router(router_).factory();
        require(routerFactory_ != address(0), "ROUTER_FACTORY_ZERO");
        require(routerFactory_.code.length > 0, "ROUTER_FACTORY_NO_CODE");

        launch = launch_;
        token = token_;
        weth = weth_;
        router = router_;
        routerFactory = routerFactory_;
        treasury = treasury_;
    }

    receive() external payable {
        revert("DIRECT_ETH_REJECTED");
    }

    fallback() external payable {
        revert("UNSUPPORTED_CALL");
    }

    /// @notice Creator tokens still held for vesting (never usable for liquidity).
    function lockedCreatorTokens() public view returns (uint256) {
        return ID17Launch(launch).manualDistributionTokens() - creatorTokensReleased;
    }

    function vestedCreatorTokens() public view returns (uint256) {
        if (!poolCreated) return 0;
        uint256 total = ID17Launch(launch).manualDistributionTokens();
        uint256 elapsed = block.timestamp - poolCreatedAt;
        if (elapsed >= CREATOR_VESTING_SECONDS) return total;
        return total * elapsed / CREATOR_VESTING_SECONDS;
    }

    function createOfficialPool(uint256 minLpMinted, uint256 deadline)
        external
        nonReentrant
        returns (address pair, uint256 liquidityTokens, uint256 wethForPool, uint256 liquidity)
    {
        require(!poolCreated, "POOL_CREATED");
        require(block.timestamp <= deadline, "DEADLINE");
        require(block.timestamp >= ID17Launch(launch).poolCreationOpensAt(), "POOL_CREATION_NOT_OPEN");

        pair = IV2Factory(routerFactory).getPair(token, weth);
        if (pair == address(0)) {
            pair = IV2Factory(routerFactory).createPair(token, weth);
        }
        require(pair.code.length > 0, "PAIR_NO_CODE");
        require(IV2PairView(pair).totalSupply() == 0, "PAIR_ALREADY_LIVE");

        // Pre-open token transfers are gated, so the pair cannot hold launch tokens. Anyone
        // may donate WETH to it; that donation can only raise the opening price and is lost
        // by the donor to the permanently locked pool.
        (uint256 tokenReserve, uint256 wethReserve) = _pairReserves(pair);
        uint256 tokenBalanceBefore = IERC20BalanceView(token).balanceOf(pair);
        uint256 wethBalanceBefore = IERC20BalanceView(weth).balanceOf(pair);
        uint256 preseededWeth = wethBalanceBefore > wethReserve ? wethBalanceBefore : wethReserve;
        require(tokenBalanceBefore == 0, "PAIR_PRESEEDED_TOKEN");

        (liquidityTokens, wethForPool) = ID17Launch(launch).claimVaultLiquidityTokens();
        require(
            IERC20BalanceView(token).balanceOf(address(this)) >= liquidityTokens + lockedCreatorTokens(),
            "VAULT_TOKEN_BALANCE"
        );
        require(liquidityTokens > 0, "NO_TOKEN_BALANCE");
        require(wethForPool > 0, "NO_WETH_FOR_POOL");
        require(IERC20BalanceView(weth).balanceOf(address(this)) >= wethForPool, "VAULT_WETH_BALANCE");

        token.safeTransfer(pair, liquidityTokens);
        weth.safeTransfer(pair, wethForPool);
        liquidity = IV2PairView(pair).mint(address(this));
        require(liquidity >= minLpMinted, "LP_SLIPPAGE");

        poolCreated = true;
        officialPair = pair;
        poolCreatedAt = block.timestamp;
        tokenUsedForPool = liquidityTokens;
        wethUsedForPool = wethForPool;
        lpMinted = liquidity;
        preseededTokenReserve = tokenReserve;
        preseededWethReserve = preseededWeth;

        ID17Launch(launch).markLiquidityPoolCreated(pair, liquidityTokens, wethForPool, liquidity);
        emit OfficialPoolCreated(pair, liquidityTokens, wethForPool, liquidity, tokenBalanceBefore, preseededWethReserve);
    }

    /// @notice Adds a late settler's LP-share WETH plus its reserved LP-token share to the
    /// official pair, minting LP to this vault (permanently locked). Called by the settling
    /// locker in the same transaction as claimLateSettlement().
    ///
    /// The deposit is balanced at the pair's live reserve ratio, so it never donates a
    /// one-sided surplus that a sandwich could capture. Whatever cannot be paired at that
    /// ratio (tokens if the price rose since launch, WETH if it fell) is burned: no one,
    /// including the late settler, gains from settling late or from moving the price.
    function mintLateLiquidity(uint256 tokenAmount, uint256 wethAmount)
        external
        nonReentrant
        returns (uint256 liquidity)
    {
        require(poolCreated, "POOL_NOT_CREATED");
        require(
            ID17FactoryView(ID17Launch(launch).factory()).isLocker(msg.sender),
            "NOT_D17_LOCKER"
        );
        require(
            IERC20BalanceView(token).balanceOf(address(this)) >= tokenAmount + lockedCreatorTokens(),
            "VAULT_TOKEN_BALANCE"
        );
        require(IERC20BalanceView(weth).balanceOf(address(this)) >= wethAmount, "VAULT_WETH_BALANCE");

        address pair = officialPair;
        (uint256 tokenReserve, uint256 wethReserve) = _pairReserves(pair);
        uint256 tokenUsed;
        uint256 wethUsed;
        if (tokenAmount > 0 && wethAmount > 0 && tokenReserve > 0 && wethReserve > 0) {
            wethUsed = tokenAmount * wethReserve / tokenReserve;
            if (wethUsed <= wethAmount) {
                tokenUsed = tokenAmount;
            } else {
                wethUsed = wethAmount;
                tokenUsed = wethAmount * tokenReserve / wethReserve;
            }
            uint256 supply = IV2PairView(pair).totalSupply();
            uint256 tokenLp = tokenUsed * supply / tokenReserve;
            uint256 wethLp = wethUsed * supply / wethReserve;
            // Too small to mint even one LP wei: burn instead of reverting, so a dust-sized
            // late position can always settle.
            if ((tokenLp < wethLp ? tokenLp : wethLp) == 0) {
                tokenUsed = 0;
                wethUsed = 0;
            }
        }

        if (tokenUsed > 0) {
            token.safeTransfer(pair, tokenUsed);
            weth.safeTransfer(pair, wethUsed);
            liquidity = IV2PairView(pair).mint(address(this));
            lateTokenUsedForLp += tokenUsed;
            lateWethUsedForLp += wethUsed;
            lateLpMinted += liquidity;
        }

        uint256 tokensBurned = tokenAmount - tokenUsed;
        uint256 wethBurned = wethAmount - wethUsed;
        if (tokensBurned > 0) {
            token.safeBurn(tokensBurned);
            lateTokensBurned += tokensBurned;
        }
        if (wethBurned > 0) {
            weth.safeTransfer(BURN_ADDRESS, wethBurned);
            lateWethBurned += wethBurned;
        }

        emit LateLiquidityAdded(msg.sender, pair, tokenUsed, wethUsed, liquidity, tokensBurned, wethBurned);
    }

    /// @notice Releases the vested part of the creator allocation to the creator wallet.
    /// Callable by anyone; the recipient is fixed in the launch's rules.
    function releaseCreatorTokens() external nonReentrant returns (uint256 amount) {
        amount = vestedCreatorTokens() - creatorTokensReleased;
        require(amount > 0, "NOTHING_VESTED");
        creatorTokensReleased += amount;
        address recipient = ID17Launch(launch).manualDistributionRecipient();
        token.safeTransfer(recipient, amount);
        emit CreatorTokensReleased(recipient, amount);
    }

    /// @notice Refund penalties paid during a launch that then failed have no pool to go
    /// to. They are burned rather than handed to the creator, the protocol or the refunder.
    function burnFailedLaunchPenalties() external nonReentrant returns (uint256 amount) {
        require(ID17Launch(launch).launchFailed(), "LAUNCH_NOT_FAILED");
        amount = IERC20BalanceView(weth).balanceOf(address(this));
        require(amount > 0, "NO_WETH");
        failedLaunchPenaltyWethBurned += amount;
        weth.safeTransfer(BURN_ADDRESS, amount);
        emit FailedLaunchPenaltiesBurned(amount);
    }

    /// @notice After pool creation every legitimate WETH flow through the vault is atomic,
    /// so any balance here is an unsolicited donation.
    function sweepExcessWethToTreasury() external nonReentrant returns (uint256 amount) {
        require(poolCreated, "POOL_NOT_CREATED");
        amount = IERC20BalanceView(weth).balanceOf(address(this));
        require(amount > 0, "NO_EXCESS_WETH");
        weth.safeTransfer(treasury, amount);
        emit ExcessWethSwept(treasury, amount);
    }

    function recoverUnsupportedTokenToTreasury(address tokenAddress, uint256 amount) external nonReentrant {
        require(amount > 0, "AMOUNT_ZERO");
        require(tokenAddress != address(0), "TOKEN_ZERO");
        require(tokenAddress != token, "D17_TOKEN_PROTECTED");
        require(tokenAddress != weth, "WETH_PROTECTED");
        require(tokenAddress != officialPair, "LP_PROTECTED");
        tokenAddress.safeTransfer(treasury, amount);
        emit UnsupportedTokenRecovered(tokenAddress, treasury, amount);
    }

    /// @notice Forced ETH is wrapped and sent as WETH so the sweep can never be blocked.
    function sweepUnexpectedEthToTreasury() external nonReentrant returns (uint256 amount) {
        amount = address(this).balance;
        require(amount > 0, "NO_ETH_BALANCE");
        IWETH(weth).deposit{value: amount}();
        weth.safeTransfer(treasury, amount);
        emit UnexpectedEthSwept(treasury, amount);
    }

    function _pairReserves(address pair) internal view returns (uint256 tokenReserve, uint256 wethReserve) {
        (uint112 reserve0, uint112 reserve1, ) = IV2PairView(pair).getReserves();
        address token0 = IV2PairView(pair).token0();
        if (token0 == token) {
            tokenReserve = uint256(reserve0);
            wethReserve = uint256(reserve1);
        } else {
            tokenReserve = uint256(reserve1);
            wethReserve = uint256(reserve0);
        }
    }
}

project/contracts/D17LiquidityVaultFacto.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {D17LiquidityVault} from "./D17LiquidityVault.sol";

contract D17LiquidityVaultFactory {
    bytes32 public constant D17_LIQUIDITY_VAULT_FACTORY_ID = keccak256("D17_LIQUIDITY_VAULT_FACTORY_V15_HARDENED");

    address public owner;
    address public launchFactory;
    bool public launchFactoryPinned;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event LaunchFactoryPinned(address indexed launchFactory);
    event LiquidityVaultCreated(address indexed launch, address indexed token, address indexed liquidityVault);

    modifier onlyOwner() {
        require(msg.sender == owner, "NOT_OWNER");
        _;
    }

    constructor(address owner_) {
        require(owner_ != address(0), "OWNER_ZERO");
        owner = owner_;
        emit OwnershipTransferred(address(0), owner_);
    }

    function pinLaunchFactory(address launchFactory_) external onlyOwner {
        require(!launchFactoryPinned, "LAUNCH_FACTORY_PINNED");
        require(launchFactory_ != address(0), "LAUNCH_FACTORY_ZERO");
        require(launchFactory_.code.length > 0, "LAUNCH_FACTORY_NO_CODE");
        launchFactory = launchFactory_;
        launchFactoryPinned = true;
        emit LaunchFactoryPinned(launchFactory_);
    }

    function renounceOwnership() external onlyOwner {
        require(launchFactoryPinned, "LAUNCH_FACTORY_UNLOCKED");
        emit OwnershipTransferred(owner, address(0));
        owner = address(0);
    }

    function deployVault(address launch, address token, address weth, address router, address treasury)
        external
        returns (address liquidityVault)
    {
        require(launchFactoryPinned && msg.sender == launchFactory, "NOT_LAUNCH_FACTORY");
        liquidityVault = address(new D17LiquidityVault(launch, token, weth, router, treasury));
        emit LiquidityVaultCreated(launch, token, liquidityVault);
    }
}

project/contracts/D17Locker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {D17SafeTransfer} from "./lib/D17SafeTransfer.sol";
import {ID17FactoryView, ID17Launch, ID17VaultLateLiquidity, IWETH} from "./interfaces/ID17.sol";

contract D17Locker {
    using D17SafeTransfer for address;

    bytes32 public constant EXPECTED_LAUNCH_ID = keccak256("D17_LAUNCH_V15_HARDENED");
    uint8 public constant ROUND_COUNT = 5;

    address public immutable owner;
    address public immutable factory;
    address public immutable weth;

    uint256 public withdrawableWeth;
    uint256 public accountedWeth;
    uint256 private entered = 1;

    struct LockerPosition {
        bool known;
        bool liquiditySettled;
        address token;
        address liquidityVault;
        bytes32 rulesHash;
        uint256 ethCommitted;
        uint256 wethCommitted;
        uint256 wethRefunded;
        uint256 penaltyPaid;
        uint256 claimedSaleTokens;
        uint256 wethSentToVault;
        uint256 wethForLp;
        uint256 treasuryWeth;
        uint256 protocolFeeWeth;
        uint256 withdrawableTokens;
        uint256 residualWeth;
        bool finalSaleTokensClaimed;
        uint256[5] roundWeth;
        uint256[5] roundSaleTokens;
        bool[5] roundRefunded;
        bool[5] roundTokensClaimed;
    }

    mapping(address => LockerPosition) public positions;

    event RoundCommitted(address indexed launch, uint8 indexed round, uint256 amount);
    event RoundRefunded(address indexed launch, uint8 indexed round, uint256 refundWeth, uint256 penaltyWeth);
    event WethWithdrawn(address indexed launch, uint256 amount);
    event VaultSettlementCompleted(
        address indexed launch,
        address indexed liquidityVault,
        address indexed settler,
        address owner,
        uint256 saleTokens,
        uint256 wethSentToVault,
        uint256 treasuryWeth,
        uint256 protocolFeeWeth,
        uint256 grossCommittedWeth,
        uint256 residualWeth
    );
    event ClaimedTokensWithdrawn(address indexed launch, uint256 amount);
    event FailedLaunchRefunded(address indexed launch, uint256 refundWeth);
    event NativeEthRecovered(address indexed recipient, uint256 amount);
    event ExcessWethRecovered(address indexed recipient, uint256 amount);

    modifier onlyOwner() {
        require(msg.sender == owner, "NOT_OWNER");
        _;
    }

    modifier nonReentrant() {
        require(entered == 1, "REENTRANT");
        entered = 2;
        _;
        entered = 1;
    }

    constructor(address owner_, address factory_, address weth_) {
        require(owner_ != address(0), "OWNER_ZERO");
        require(factory_ != address(0), "FACTORY_ZERO");
        require(weth_ != address(0), "WETH_ZERO");
        owner = owner_;
        factory = factory_;
        weth = weth_;
    }

    receive() external payable {
        revert("DIRECT_ETH_REJECTED");
    }

    fallback() external payable {
        revert("UNSUPPORTED_CALL");
    }

    function verifyLaunch(address launch, bytes32 expectedRulesHash) public view returns (bool) {
        require(launch.code.length > 0, "NO_CODE");
        ID17Launch candidate = ID17Launch(launch);
        require(candidate.D17_LAUNCH_ID() == EXPECTED_LAUNCH_ID, "BAD_LAUNCH_ID");
        require(candidate.weth() == weth, "BAD_WETH");
        require(candidate.rulesHash() == expectedRulesHash, "BAD_RULES");
        require(ID17FactoryView(factory).isCanonicalLaunch(launch, expectedRulesHash), "NOT_CANONICAL");
        return true;
    }

    function lockedWeth(address launch) external view returns (uint256) {
        return positions[launch].wethCommitted;
    }

    function roundPosition(address launch, uint8 round)
        external
        view
        returns (uint256 roundWeth, uint256 roundSaleTokens, bool refunded, bool tokensClaimed)
    {
        require(round < ROUND_COUNT, "ROUND");
        LockerPosition storage position = positions[launch];
        return (
            position.roundWeth[round],
            position.roundSaleTokens[round],
            position.roundRefunded[round],
            position.roundTokensClaimed[round]
        );
    }

    function commitToRound(address launch, uint8 round, bytes32 expectedRulesHash)
        public
        payable
        onlyOwner
        nonReentrant
    {
        require(msg.value > 0, "NO_ETH");
        require(round < ROUND_COUNT, "ROUND");
        verifyLaunch(launch, expectedRulesHash);

        LockerPosition storage position = positions[launch];
        require(!position.liquiditySettled, "LIQUIDITY_SETTLED");

        IWETH(weth).deposit{value: msg.value}();
        accountedWeth += msg.value;

        position.known = true;
        position.rulesHash = expectedRulesHash;
        position.token = ID17Launch(launch).token();
        position.ethCommitted += msg.value;
        position.wethCommitted += msg.value;
        position.roundWeth[round] += msg.value;

        ID17Launch(launch).recordRoundCommitment(round, msg.value);
        emit RoundCommitted(launch, round, msg.value);
    }

    function refundCurrentRound(address launch) public onlyOwner nonReentrant {
        LockerPosition storage position = positions[launch];
        require(position.known, "UNKNOWN_LAUNCH");
        require(!position.liquiditySettled, "LIQUIDITY_SETTLED");

        (uint8 round, uint256 refundWeth, uint256 penaltyWeth) = ID17Launch(launch).releaseRoundRefund();
        uint256 gross = refundWeth + penaltyWeth;
        require(gross > 0, "NO_REFUND");
        require(position.roundWeth[round] >= gross, "ROUND_WETH_BALANCE");
        require(position.wethCommitted >= gross, "LOCKED_WETH_BALANCE");

        position.roundWeth[round] -= gross;
        position.wethCommitted -= gross;
        position.roundRefunded[round] = true;
        position.wethRefunded += refundWeth;
        position.penaltyPaid += penaltyWeth;
        position.residualWeth += refundWeth;
        withdrawableWeth += refundWeth;
        if (penaltyWeth > 0) accountedWeth -= penaltyWeth;

        // Penalties deepen the official pool (vault), they never reach the creator.
        if (penaltyWeth > 0) weth.safeTransfer(ID17Launch(launch).liquidityVault(), penaltyWeth);
        emit RoundRefunded(launch, round, refundWeth, penaltyWeth);
    }

    function withdrawUnlockedWeth(address launch, uint256 amount) public onlyOwner nonReentrant {
        require(amount > 0, "AMOUNT_ZERO");
        LockerPosition storage position = positions[launch];
        require(amount <= position.residualWeth, "POSITION_WETH_BALANCE");
        require(amount <= withdrawableWeth, "WETH_BALANCE");
        position.residualWeth -= amount;
        withdrawableWeth -= amount;
        accountedWeth -= amount;
        weth.safeTransfer(owner, amount);
        emit WethWithdrawn(launch, amount);
    }

    function refundFailedLaunch(address launch, bytes32 expectedRulesHash) public onlyOwner nonReentrant {
        verifyLaunch(launch, expectedRulesHash);
        LockerPosition storage position = positions[launch];
        require(position.known, "UNKNOWN_LAUNCH");
        require(!position.liquiditySettled, "LIQUIDITY_SETTLED");

        uint256 localRefund;
        for (uint8 round; round < ROUND_COUNT; round++) localRefund += position.roundWeth[round];

        uint256 refundWeth = ID17Launch(launch).releaseFailedRefund();
        require(refundWeth == localRefund, "FAILED_REFUND_MISMATCH");
        require(position.wethCommitted >= refundWeth, "LOCKED_WETH_BALANCE");

        for (uint8 round; round < ROUND_COUNT; round++) {
            if (position.roundWeth[round] > 0) {
                position.roundWeth[round] = 0;
                position.roundRefunded[round] = true;
            }
        }

        position.wethCommitted -= refundWeth;
        position.wethRefunded += refundWeth;
        position.residualWeth += refundWeth;
        withdrawableWeth += refundWeth;
        emit FailedLaunchRefunded(launch, refundWeth);
    }

    function settleAndClaim(address launch, bytes32 expectedRulesHash) public onlyOwner nonReentrant returns (uint256 claimedSaleTokens) {
        verifyLaunch(launch, expectedRulesHash);
        claimedSaleTokens = _settleVaultPosition(launch);
    }

    function settleAfterGrace(address launch) public nonReentrant returns (uint256 claimedSaleTokens) {
        LockerPosition storage position = positions[launch];
        require(position.known, "UNKNOWN_LAUNCH");
        verifyLaunch(launch, position.rulesHash);
        require(ID17Launch(launch).finalized(), "NOT_FINALIZED");
        require(block.timestamp >= ID17Launch(launch).poolCreationOpensAt(), "GRACE_OPEN");
        claimedSaleTokens = _settleVaultPosition(launch);
    }

    function _settleVaultPosition(address launch) internal returns (uint256 claimedSaleTokens) {
        LockerPosition storage position = positions[launch];
        require(position.known, "UNKNOWN_LAUNCH");
        require(!position.liquiditySettled, "LIQUIDITY_SETTLED");

        uint256 previewTotal;
        uint256 grossCommittedWeth;
        for (uint8 round; round < ROUND_COUNT; round++) {
            uint256 roundAmount = ID17Launch(launch).previewRoundTokens(address(this), round);
            position.roundSaleTokens[round] = roundAmount;
            if (roundAmount > 0) position.roundTokensClaimed[round] = true;
            previewTotal += roundAmount;
            grossCommittedWeth += position.roundWeth[round];
        }

        // After pool creation the launch routes settlement through the late top-up path:
        // identical sale tokens, WETH cost, and fee, with the LP-share WETH still entering
        // the official pool alongside the position's reserved LP-token share.
        bool late = ID17Launch(launch).liquidityPoolCreated();
        uint256 wethForVault;
        uint256 treasuryWeth;
        uint256 protocolFeeWeth;
        uint256 lateLpTokens;
        if (late) {
            (claimedSaleTokens, wethForVault, treasuryWeth, protocolFeeWeth, lateLpTokens) =
                ID17Launch(launch).claimLateSettlement();
        } else {
            (claimedSaleTokens, wethForVault, treasuryWeth, protocolFeeWeth) = ID17Launch(launch).claimVaultSettlement();
        }
        require(claimedSaleTokens == previewTotal, "FINAL_CLAIM_MISMATCH");
        uint256 spent = wethForVault + treasuryWeth + protocolFeeWeth;
        require(position.wethCommitted >= spent, "LOCKED_WETH_BALANCE");

        position.liquiditySettled = true;
        position.finalSaleTokensClaimed = true;
        position.claimedSaleTokens += claimedSaleTokens;
        position.withdrawableTokens += claimedSaleTokens;
        position.liquidityVault = ID17Launch(launch).liquidityVault();
        position.wethSentToVault = wethForVault;
        position.wethForLp = wethForVault;
        position.treasuryWeth = treasuryWeth;
        position.protocolFeeWeth = protocolFeeWeth;
        position.token = ID17Launch(launch).token();
        position.wethCommitted -= spent;

        if (wethForVault > 0) weth.safeTransfer(position.liquidityVault, wethForVault);
        if (treasuryWeth > 0) weth.safeTransfer(ID17Launch(launch).treasury(), treasuryWeth);
        if (protocolFeeWeth > 0) weth.safeTransfer(ID17Launch(launch).protocolFeeRecipient(), protocolFeeWeth);
        accountedWeth -= spent;

        if (late) {
            ID17VaultLateLiquidity(position.liquidityVault).mintLateLiquidity(lateLpTokens, wethForVault);
        }

        position.residualWeth += position.wethCommitted;
        withdrawableWeth += position.wethCommitted;
        position.wethCommitted = 0;

        emit VaultSettlementCompleted(
            launch,
            position.liquidityVault,
            msg.sender,
            owner,
            claimedSaleTokens,
            wethForVault,
            treasuryWeth,
            protocolFeeWeth,
            grossCommittedWeth,
            position.residualWeth
        );
    }

    function withdrawUnlockedTokens(address launch, uint256 amount) public onlyOwner nonReentrant {
        require(amount > 0, "AMOUNT_ZERO");
        LockerPosition storage position = positions[launch];
        require(position.token != address(0), "TOKEN_MISSING");
        require(ID17Launch(launch).tradingOpen(), "TOKEN_WITHDRAW_LOCKED");
        require(amount <= position.withdrawableTokens, "TOKEN_BALANCE");
        position.withdrawableTokens -= amount;
        position.token.safeTransfer(owner, amount);
        emit ClaimedTokensWithdrawn(launch, amount);
    }

    function recoverNativeEth(address recipient, uint256 amount) external onlyOwner nonReentrant {
        require(recipient != address(0), "RECIPIENT_ZERO");
        require(amount > 0, "AMOUNT_ZERO");
        require(amount <= address(this).balance, "ETH_BALANCE");
        (bool ok, ) = recipient.call{value: amount}("");
        require(ok, "ETH_TRANSFER_FAILED");
        emit NativeEthRecovered(recipient, amount);
    }

    function recoverExcessWeth(address recipient, uint256 amount) public onlyOwner nonReentrant {
        require(recipient != address(0), "RECIPIENT_ZERO");
        require(amount > 0, "AMOUNT_ZERO");
        uint256 balance = IWETH(weth).balanceOf(address(this));
        require(balance > accountedWeth, "NO_EXCESS_WETH");
        require(amount <= balance - accountedWeth, "EXCESS_WETH_BALANCE");
        weth.safeTransfer(recipient, amount);
        emit ExcessWethRecovered(recipient, amount);
    }

}

project/contracts/D17LockerFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {D17Locker} from "./D17Locker.sol";

interface ID17LockerRegistry {
    function weth() external view returns (address);
    function registerLockerFor(address lockerOwner, address locker) external;
}

contract D17LockerFactory {
    address public immutable d17Factory;

    event LockerCreated(address indexed owner, address indexed locker);

    constructor(address d17Factory_) {
        require(d17Factory_ != address(0), "FACTORY_ZERO");
        require(d17Factory_.code.length > 0, "FACTORY_NO_CODE");
        d17Factory = d17Factory_;
    }

    function createLockerFor(address lockerOwner) external returns (address locker) {
        require(lockerOwner != address(0), "OWNER_ZERO");
        require(msg.sender == lockerOwner, "ONLY_SELF");
        ID17LockerRegistry registry = ID17LockerRegistry(d17Factory);
        locker = address(new D17Locker(lockerOwner, d17Factory, registry.weth()));
        registry.registerLockerFor(lockerOwner, locker);
        emit LockerCreated(lockerOwner, locker);
    }
}

project/contracts/D17Token.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ID17LaunchFactory} from "./interfaces/ID17LaunchFactory.sol";

interface ID17TokenGateV2Factory {
    function getPair(address tokenA, address tokenB) external view returns (address);
}

interface ID17TokenGateLaunch {
    function tradingOpen() external view returns (bool);
}

contract D17Token {
    bytes32 public constant D17_TOKEN_ID = keccak256("D17_TOKEN_V15_HARDENED");

    string public name;
    string public symbol;
    uint8 public constant decimals = 18;
    uint256 public immutable maxSupply;
    uint256 public totalSupply;
    address public owner;
    address public launch;
    address public d17Factory;
    address public weth;
    address public routerFactory;
    address public liquidityVault;
    uint256 public tradingOpenAt;
    bool public mintingClosed;
    bool public tradingGateConfigured;
    bool public metadataConfigured;
    string public description;
    string public logoSvgUri;
    bytes32 public metadataHash;

    struct MetadataLink {
        string linkType;
        string url;
    }

    MetadataLink[] private metadataLinks;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event MintingClosed();
    event TradingGateConfigured(
        address indexed launch,
        address indexed d17Factory,
        address indexed weth,
        address routerFactory,
        address liquidityVault,
        uint256 tradingOpenAt
    );
    event TokenMetadataConfigured(
        bytes32 indexed metadataHash,
        string description,
        string logoSvgUri,
        string[] linkTypes,
        string[] linkUrls
    );
    event ContractURIUpdated();

    modifier onlyOwner() {
        require(msg.sender == owner, "NOT_OWNER");
        _;
    }

    constructor(address owner_, string memory name_, string memory symbol_, uint256 maxSupply_) {
        require(owner_ != address(0), "OWNER_ZERO");
        require(bytes(name_).length > 0 && bytes(name_).length <= 64, "NAME");
        require(bytes(symbol_).length > 0 && bytes(symbol_).length <= 16, "SYMBOL");
        _validateJsonSafe(name_, "NAME_JSON");
        _validateJsonSafe(symbol_, "SYMBOL_JSON");
        require(maxSupply_ > 0, "SUPPLY_ZERO");
        owner = owner_;
        name = name_;
        symbol = symbol_;
        maxSupply = maxSupply_;
        emit OwnershipTransferred(address(0), owner_);
    }

    function configureTradingGate(
        address launch_,
        address d17Factory_,
        address weth_,
        address routerFactory_,
        address liquidityVault_,
        uint256 tradingOpenAt_
    ) external onlyOwner {
        require(!tradingGateConfigured, "TRADING_GATE_CONFIGURED");
        require(launch_ != address(0), "LAUNCH_ZERO");
        require(d17Factory_ != address(0), "FACTORY_ZERO");
        require(weth_ != address(0), "WETH_ZERO");
        require(routerFactory_ != address(0), "ROUTER_FACTORY_ZERO");
        require(liquidityVault_ != address(0), "VAULT_ZERO");
        require(launch_.code.length > 0, "LAUNCH_NO_CODE");
        require(d17Factory_.code.length > 0, "FACTORY_NO_CODE");
        require(weth_.code.length > 0, "WETH_NO_CODE");
        require(routerFactory_.code.length > 0, "ROUTER_FACTORY_NO_CODE");
        require(liquidityVault_.code.length > 0, "VAULT_NO_CODE");
        require(tradingOpenAt_ > block.timestamp, "TRADING_OPEN_NOW");

        launch = launch_;
        d17Factory = d17Factory_;
        weth = weth_;
        routerFactory = routerFactory_;
        liquidityVault = liquidityVault_;
        tradingOpenAt = tradingOpenAt_;
        tradingGateConfigured = true;

        emit TradingGateConfigured(launch_, d17Factory_, weth_, routerFactory_, liquidityVault_, tradingOpenAt_);
    }

    function configureMetadata(
        string calldata description_,
        string calldata logoSvgUri_,
        ID17LaunchFactory.Link[] calldata links_
    ) external onlyOwner {
        require(!metadataConfigured, "METADATA_CONFIGURED");
        description = description_;
        logoSvgUri = logoSvgUri_;
        for (uint256 i; i < links_.length; i++) {
            metadataLinks.push(MetadataLink({linkType: links_[i].linkType, url: links_[i].url}));
        }
        metadataHash = keccak256(abi.encode(name, symbol, description_, logoSvgUri_, links_));
        metadataConfigured = true;

        emit TokenMetadataConfigured(metadataHash, description_, logoSvgUri_, _metadataLinkTypes(), _metadataLinkUrls());
        emit ContractURIUpdated();
    }

    function tradingOpen() external view returns (bool) {
        return _launchTradingOpen();
    }

    function linkCount() external view returns (uint256) {
        return metadataLinks.length;
    }

    function links(uint256 index) external view returns (string memory linkType, string memory url) {
        require(index < metadataLinks.length, "LINK_INDEX");
        MetadataLink storage link = metadataLinks[index];
        return (link.linkType, link.url);
    }

    function contractURI() external view returns (string memory) {
        return string(abi.encodePacked("data:application/json;charset=utf-8,", _contractMetadataJson()));
    }

    function canonicalPair() public view returns (address) {
        if (!tradingGateConfigured) return address(0);
        return ID17TokenGateV2Factory(routerFactory).getPair(address(this), weth);
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            require(allowed >= amount, "ALLOWANCE");
            unchecked {
                allowance[from][msg.sender] = allowed - amount;
            }
        }
        _transfer(from, to, amount);
        return true;
    }

    function burn(uint256 amount) external {
        // Pre-open burns are restricted to the launch (unsold sale-token burn at
        // finalization). The launch factory mints the manual allocation before trading
        // opens; without this gate the creator could change the visible supply/tokenomics
        // before the launch outcome is known. After trading opens any holder may burn.
        require(msg.sender == launch || _launchTradingOpen(), "BURN_BEFORE_OPEN");
        require(balanceOf[msg.sender] >= amount, "BALANCE");
        unchecked {
            balanceOf[msg.sender] -= amount;
            totalSupply -= amount;
        }
        emit Transfer(msg.sender, address(0), amount);
    }

    function mint(address to, uint256 amount) external onlyOwner {
        require(!mintingClosed, "MINTING_CLOSED");
        require(totalSupply + amount <= maxSupply, "CAP");
        require(to != address(0), "TO_ZERO");
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function closeMinting() external onlyOwner {
        require(!mintingClosed, "MINTING_CLOSED");
        mintingClosed = true;
        emit MintingClosed();
    }

    function renounceOwnership() external onlyOwner {
        emit OwnershipTransferred(owner, address(0));
        owner = address(0);
    }

    function _transfer(address from, address to, uint256 amount) internal {
        require(to != address(0), "TO_ZERO");
        require(_transferAllowedBeforeOpen(from, to), "TRADING_CLOSED");
        require(balanceOf[from] >= amount, "BALANCE");
        if (amount == 0) {
            emit Transfer(from, to, 0);
            return;
        }
        unchecked {
            balanceOf[from] -= amount;
            balanceOf[to] += amount;
        }
        emit Transfer(from, to, amount);
    }

    function _transferAllowedBeforeOpen(address from, address to) private view returns (bool) {
        if (!tradingGateConfigured) return false;
        if (from == launch) return true;

        address pair = canonicalPair();
        if (pair != address(0) && to == pair && from == liquidityVault) return true;

        if (_launchTradingOpen()) return true;

        return false;
    }

    function _launchTradingOpen() private view returns (bool) {
        if (!tradingGateConfigured) return false;
        try ID17TokenGateLaunch(launch).tradingOpen() returns (bool open) {
            return open;
        } catch {
            return false;
        }
    }

    function _contractMetadataJson() private view returns (bytes memory) {
        bytes memory json = abi.encodePacked(
            '{"name":"',
            name,
            '","symbol":"',
            symbol,
            '","description":"',
            description,
            '","image":"',
            logoSvgUri,
            '","links":['
        );

        for (uint256 i; i < metadataLinks.length; i++) {
            MetadataLink storage link = metadataLinks[i];
            if (i > 0) json = abi.encodePacked(json, ",");
            json = abi.encodePacked(json, '{"type":"', link.linkType, '","url":"', link.url, '"}');
        }

        return abi.encodePacked(json, "]}");
    }

    function _metadataLinkTypes() private view returns (string[] memory linkTypes) {
        linkTypes = new string[](metadataLinks.length);
        for (uint256 i; i < metadataLinks.length; i++) {
            linkTypes[i] = metadataLinks[i].linkType;
        }
    }

    function _metadataLinkUrls() private view returns (string[] memory linkUrls) {
        linkUrls = new string[](metadataLinks.length);
        for (uint256 i; i < metadataLinks.length; i++) {
            linkUrls[i] = metadataLinks[i].url;
        }
    }

    function _validateJsonSafe(string memory value, string memory reason) private pure {
        bytes memory data = bytes(value);
        for (uint256 i; i < data.length; i++) {
            bytes1 char = data[i];
            if (char == 0x22 || char == 0x5c || char < 0x20) revert(reason);
        }
    }
}

project/contracts/D17TokenFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {D17Token} from "./D17Token.sol";

contract D17TokenFactory {
    bytes32 public constant D17_TOKEN_FACTORY_ID = keccak256("D17_TOKEN_FACTORY_V15_HARDENED");

    address public owner;
    address public launchFactory;
    bool public launchFactoryPinned;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event LaunchFactoryPinned(address indexed launchFactory);
    event TokenCreated(address indexed token, string name, string symbol, uint256 maxSupply);

    modifier onlyOwner() {
        require(msg.sender == owner, "NOT_OWNER");
        _;
    }

    constructor(address owner_) {
        require(owner_ != address(0), "OWNER_ZERO");
        owner = owner_;
        emit OwnershipTransferred(address(0), owner_);
    }

    function pinLaunchFactory(address launchFactory_) external onlyOwner {
        require(!launchFactoryPinned, "LAUNCH_FACTORY_PINNED");
        require(launchFactory_ != address(0), "LAUNCH_FACTORY_ZERO");
        require(launchFactory_.code.length > 0, "LAUNCH_FACTORY_NO_CODE");
        launchFactory = launchFactory_;
        launchFactoryPinned = true;
        emit LaunchFactoryPinned(launchFactory_);
    }

    function renounceOwnership() external onlyOwner {
        require(launchFactoryPinned, "LAUNCH_FACTORY_UNLOCKED");
        emit OwnershipTransferred(owner, address(0));
        owner = address(0);
    }

    function deployToken(address tokenOwner, string calldata name, string calldata symbol, uint256 maxSupply)
        external
        returns (address token)
    {
        require(launchFactoryPinned && msg.sender == launchFactory, "NOT_LAUNCH_FACTORY");
        token = address(new D17Token(tokenOwner, name, symbol, maxSupply));
        emit TokenCreated(token, name, symbol, maxSupply);
    }
}

project/contracts/interfaces/ID17.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface ID17Launch {
    function D17_LAUNCH_ID() external view returns (bytes32);
    function rulesHash() external view returns (bytes32);
    function metadataHash() external view returns (bytes32);
    function token() external view returns (address);
    function weth() external view returns (address);
    function treasury() external view returns (address);
    function protocolFeeRecipient() external view returns (address);
    function launchFailed() external view returns (bool);
    function factory() external view returns (address);
    function liquidityVault() external view returns (address);
    function tradingOpenAt() external view returns (uint256);
    function tradingOpen() external view returns (bool);
    function liquidityPoolCreated() external view returns (bool);
    function settlementStartsAt() external view returns (uint256);
    function settlementSeconds() external view returns (uint32);
    function poolCreationOpensAt() external view returns (uint256);
    function settledLiquidityWeth() external view returns (uint256);
    function poolSettledLiquidityWeth() external view returns (uint256);
    function poolSettledCommittedWeth() external view returns (uint256);
    function lateSettledCommittedWeth() external view returns (uint256);
    function lateSettledLiquidityWeth() external view returns (uint256);
    function manualDistributionTokens() external view returns (uint256);
    function manualDistributionRecipient() external view returns (address);
    function activeRound() external view returns (uint8);
    function activeRefundWindow() external view returns (uint8);
    function finalized() external view returns (bool);
    function allFinalCommitmentsSettled() external view returns (bool);
    function anchorPriceWad() external view returns (uint256);
    function roundBaseTokenAllocation(uint8 round) external view returns (uint256);
    function roundTokenAllocation(uint8 round) external view returns (uint256);
    function roundSoldTokens(uint8 round) external view returns (uint256);
    function roundAnchorTargetWeth(uint8 round) external view returns (uint256);
    function roundAnchorUnderfillRemainingWeth(uint8 round) external view returns (uint256);
